// ── TEMPERS (AK §2.4) ────
// One table drives every temper effect in the game. Each temper is built to be worth choosing: an
// offensive edge, a defensive edge, a ranged/larcenous edge, or raw survivability.
// meleeHit % added to this character's own melee to-hit
// archeryHit % added to this character's own archery to-hit
// defence % subtracted from anyone attacking them in melee
// meleeDamage flat bonus to melee damage dealt
// damageSoak flat reduction on incoming melee damage (never below 1)
// withdrawMod % added to breaking out of melee back to firing range
// stealMod % added to Steal attempts
// fleeMod % added to flee attempts
// fleeAt HP fraction below which they start looking for a way out
// fleeUrge chance per round of acting on that impulse
// losingOnly only considers flight while actually behind on HP
// rageHp [min,max] extra hit points gained for the fight (null = none)
// hitSoakPct fraction of each incoming MELEE or ARCHERY hit shrugged off (0 = none)
// secondWind fraction of max HP recovered, once per fight, on first dropping below fleeAt+0.05
// riposte chance to counterattack when a MELEE attack against them misses
// defence ALSO lowers the 80% melee hit ceiling for anyone attacking them
// openingShot the first move up to firing range in a fight cannot fail
// mercy may beg for mercy when felled instead of dying
const TEMPER_TRAITS={
  Berserk:  {meleeHit:18, archeryHit:0,  defence:-10, meleeDamage:3, damageSoak:0, hitSoakPct:0.12, withdrawMod:-10, stealMod:0,  fleeMod:-20, fleeAt:0.15, fleeUrge:0.20, losingOnly:false, rageHp:null,  secondWind:0,    riposte:0,    openingShot:false, mercy:false},
  Brave:    {meleeHit:12, archeryHit:8,  defence:4,   meleeDamage:1, damageSoak:0, hitSoakPct:0,    withdrawMod:0,   stealMod:0,  fleeMod:10,  fleeAt:0.25, fleeUrge:0.30, losingOnly:true,  rageHp:null,  secondWind:0.26, riposte:0,    openingShot:false, mercy:false},
  Cautious: {meleeHit:0,  archeryHit:0,  defence:14,  meleeDamage:0, damageSoak:2, hitSoakPct:0,    withdrawMod:10,  stealMod:0,  fleeMod:20,  fleeAt:0.40, fleeUrge:0.35, losingOnly:false, rageHp:null,  secondWind:0,    riposte:0.40, openingShot:false, mercy:false},
  Cowardly: {meleeHit:-4, archeryHit:22, defence:6,   meleeDamage:0, damageSoak:0, hitSoakPct:0,    withdrawMod:15,  stealMod:15, fleeMod:30,  fleeAt:0.40, fleeUrge:0.40, losingOnly:false, rageHp:null,  secondWind:0,    riposte:0,    openingShot:true,  mercy:true},
  // A true no-temper profile — all zeros, no second wind, no mercy. Feature guardians (the
  // monsters/beasts on a treasure site) use this so they neither gain hero-style temper perks nor
  // print a temper like "(Brave)" in combat lines. NOT in TEMPERS_P, so it is never assigned to a
  // hero.
  None:     {meleeHit:0,  archeryHit:0,  defence:0,   meleeDamage:0, damageSoak:0, hitSoakPct:0,    withdrawMod:0,   stealMod:0,  fleeMod:0,   fleeAt:0.25, fleeUrge:0,    losingOnly:false, rageHp:null,  secondWind:0,    riposte:0,    openingShot:false, mercy:false},
};

