// Comprehensive magic items — one or more per skill, plus special army-type bonuses
const ALL_MAGIC_ITEMS_P=[
  // ── Melee ──
  // ── POWERFUL WEAPONS, OPEN TO ANYONE ────
  // Every Powerful-tier weapon in the game was gated by race or alignment, so a Human hero of a
  // Neutral realm had NO Powerful weapon to find at all — the tier-3 weapon slot was a downgrade
  // rather than a prize. Twenty unrestricted designs, one focus for each school, at +3 to their
  // stat (the gated designs keep the top of the band, upgraded so a restriction still buys
  // something). The weapon band at tier 3 is widened to 25 to hold them — see ITEM_TIER_TARGET.
  {name:'Sundered Greatsword',desc:'Melee +3',lore:'A blade broken and reforged so many times that the seams have become its strength. Melee counts 3 levels higher.',effect:{stat:'melee',bonus:3},slot:'weapon',tier:3},
  {name:'Kingsteel Longsword',desc:'Melee +3, and +1 damage on every melee hit.',lore:'Steel of the old royal foundries, still unmatched by anything poured since. Melee counts 3 levels higher and every melee hit deals 1 extra damage.',effect:{stat:'melee',bonus:3,pc:{dmgBonus:1}},slot:'weapon',tier:3},
  {name:'Warden\'s Poleaxe',desc:'Melee +3, and +8% to hit.',lore:'A gate-guard\'s weapon, long enough to keep trouble at arm\'s length. Melee counts 3 levels higher and you strike at +8% to hit.',effect:{stat:'melee',bonus:3,pc:{hitBonus:8}},slot:'weapon',tier:3},
  {name:'Bleakiron Maul',desc:'Melee +3, and +1 damage on every melee hit.',lore:'Dull grey, absurdly heavy, and it has never once glanced off. Melee counts 3 levels higher and every melee hit deals 1 extra damage.',effect:{stat:'melee',bonus:3,pc:{dmgBonus:1}},slot:'weapon',tier:3},
  {name:'Duellist\'s Rapier',desc:'Melee +3, and +8% to hit.',lore:'Light, quick and entirely unsuited to a battlefield; in a single combat there is nothing better. Melee counts 3 levels higher and you strike at +8% to hit.',effect:{stat:'melee',bonus:3,pc:{hitBonus:8}},slot:'weapon',tier:3},
  {name:'Riverstone Axe',desc:'Melee +3',lore:'A head of grey river stone bound to a haft of black ash, older than any forge. Melee counts 3 levels higher.',effect:{stat:'melee',bonus:3},slot:'weapon',tier:3},
  {name:'Oathkeeper\'s Blade',desc:'Melee +3, and foes -6% to hit you.',lore:'Swear on it once and you will find you cannot let your guard fall. Melee counts 3 levels higher and the foe fights at -6% to hit.',effect:{stat:'melee',bonus:3,pc:{aura:6}},slot:'weapon',tier:3},
  {name:'Serpent-Fang Sabre',desc:'Melee +3, and +1 damage on every melee hit.',lore:'Curved like a striking snake, and about as forgiving. Melee counts 3 levels higher and every melee hit deals 1 extra damage.',effect:{stat:'melee',bonus:3,pc:{dmgBonus:1}},slot:'weapon',tier:3},
  {name:'Warden-Bow of the Marches',desc:'Archery +3',lore:'A border-watch bow that takes two men to string and one to loose. Archery counts 3 levels higher.',effect:{stat:'archery',bonus:3},slot:'weapon',tier:3},
  {name:'Hunter\'s Arbalest',desc:'Archery +3, and +1 damage on every hit.',lore:'Slow to wind and impossible to argue with. Archery counts 3 levels higher and every hit deals 1 extra damage.',effect:{stat:'archery',bonus:3,pc:{dmgBonus:1}},slot:'weapon',tier:3},
  {name:'Stormwood Longbow',desc:'Archery +3, and +8% to hit.',lore:'Cut from a tree that was struck twice and grew straighter for it. Archery counts 3 levels higher and you shoot at +8% to hit.',effect:{stat:'archery',bonus:3,pc:{hitBonus:8}},slot:'weapon',tier:3},
  {name:'Falconer\'s Recurve',desc:'Archery +3',lore:'Short, savage, and made to be drawn from the saddle. Archery counts 3 levels higher.',effect:{stat:'archery',bonus:3},slot:'weapon',tier:3},
  {name:'Ironthread Crossbow',desc:'Archery +3, and +1 damage on every hit.',lore:'Strung with drawn iron wire; the bolt arrives before the sound does. Archery counts 3 levels higher and every hit deals 1 extra damage.',effect:{stat:'archery',bonus:3,pc:{dmgBonus:1}},slot:'weapon',tier:3},
  {name:'Windcut Flatbow',desc:'Archery +3, and +8% to hit.',lore:'A plain stave of yew that seems to decide where the arrow goes. Archery counts 3 levels higher and you shoot at +8% to hit.',effect:{stat:'archery',bonus:3,pc:{hitBonus:8}},slot:'weapon',tier:3},
  {name:'Staff of the Burning Year',desc:'Elemental Magic +3',lore:'Charred at one end and warm at the other, whatever the season. Elemental Magic counts 3 levels higher.',effect:{stat:'elemental',bonus:3},slot:'weapon',tier:3},
  {name:'Rod of Quiet Hours',desc:'Psychic Magic +3',lore:'Holding it, you find the room has gone very still and you can hear yourself think. Psychic Magic counts 3 levels higher.',effect:{stat:'psychic',bonus:3},slot:'weapon',tier:3},
  {name:'Sceptre of the Pale Hour',desc:'Necromancy +3',lore:'Bone-white, cold, and heavier at dusk. Necromancy counts 3 levels higher.',effect:{stat:'necromancy',bonus:3},slot:'weapon',tier:3},
  {name:'Staff of the Shrouded Lamp',desc:'Illusory Magic +3',lore:'The lamp at its head sheds no light and casts a great many shadows. Illusory Magic counts 3 levels higher.',effect:{stat:'illusory',bonus:3},slot:'weapon',tier:3},
  {name:'Crozier of the Kept Vigil',desc:'White Magic +3',lore:'Carried through one long night by somebody who did not sit down. White Magic counts 3 levels higher.',effect:{stat:'white',bonus:3},slot:'weapon',tier:3},
  {name:'Stave of the Deep Wood',desc:'Druid Mastery +3',lore:'Still green, still growing, and it will put out a leaf if you leave it in water. Druid Mastery counts 3 levels higher.',effect:{stat:'druid',bonus:3},slot:'weapon',tier:3},
  {name:'Blade of Fury',desc:'Melee +2',lore:'A sword that hums with barely held anger; those who bear it strike faster and harder than their training alone allows. Melee skill counts as 2 levels higher in personal combat.',effect:{stat:'melee',bonus:2},tier:2},
  {name:'Warbringer Gauntlets',desc:'Melee +1, +2 damage per successful melee attack in personal combat',lore:'Iron-banded gauntlets that drive every blow home with bone-jarring weight. Melee skill counts 1 level higher, and each melee hit you land in personal combat deals 2 extra damage.',effect:{stat:'melee',bonus:1},tier:1},
  // ── Archery ──
  {name:'Elven Longbow',desc:'Archery +2',lore:'A bow of pale silverwood, strung by elven hands, that seems to steady the arm and quiet the breath. Archery skill counts as 2 levels higher.',effect:{stat:'archery',bonus:2},tier:2},
  {name:'Quiver of the Hawk',desc:'Archery +1. In the pre-battle archery phase, your missile units each fire two volleys instead of one.',lore:'Arrows drawn from this quiver fly true and fast, and the quiver never seems to empty. Archery skill counts 1 level higher, and in the pre-battle archery phase every missile unit you lead fires two volleys instead of one.',effect:{stat:'archery',bonus:1},tier:1},
  // ── Tactical ──
  {name:'Tome of Tactics',desc:'Tactical +2',lore:'A battered manual of formations, feints and flank marches, annotated in a dozen hands over a dozen wars. Tactical skill counts as 2 levels higher.',effect:{stat:'tactical',bonus:2},tier:2},
  {name:'War Drum of the Ancients',desc:'Tactical +1, and 20% of the armies you lead fight one quality tier higher in each battle',lore:'A great hide drum whose beat drives soldiers to feats beyond their training. Tactical skill counts 1 level higher, and in each battle one fifth of the armies you lead fight one quality tier higher than they are.',effect:{stat:'tactical',bonus:1},drumTierUp:true,tier:1},
  // ── March ──
  {name:'Boots of the Wind',desc:'March +2',lore:'Light as a feather and always dry, these boots eat the miles beneath them. March skill counts as 2 levels higher, so you move further each turn.',effect:{stat:'march',bonus:2},tier:2},
  {name:'Traveller\'s Cloak',desc:'March +1, +20% province exploration when you move into a province',lore:'Weather-stained travelling gear that seems to know every hidden path and short cut. March skill counts 1 level higher, and moving into a province explores an extra 20% of it as you pass.',effect:{stat:'march',bonus:1},exploreMove:20,tier:1},
  // ── Naval ──
  {name:'Admiral\'s Spyglass',desc:'Naval +2, and all fleets you lead: +2 strength',lore:'Through this brass lens the sea gives up its currents, shoals and hidden reefs. Naval skill counts as 2 levels higher, and every fleet you lead fights at +2 strength.',effect:{stat:'naval',bonus:2},tier:2},
  {name:'Sea Chart of the Deep',desc:'Naval +1, and all fleets you lead: +1 strength',lore:'An old chart of hidden currents and safe channels, inked by a navigator who never lost a ship. Naval skill counts 1 level higher, and every fleet you lead fights at +1 strength.',effect:{stat:'naval',bonus:1},fleetStr:1,tier:1},
  // ── Sage ──
  {name:'Sage\'s Crown',desc:'Sage +2',lore:'A slim circlet said to have graced the brow of the old Empire\'s first librarian; wearing it, half-remembered lore comes flooding back. Sage skill counts as 2 levels higher.',effect:{stat:'sage',bonus:2},tier:2},
  {name:'Philosopher\'s Lens',desc:'Sage +1, reveals one random lair when exploring',lore:'A scholar\'s glass that shows the world a little more truly than it is. Sage skill counts 1 level higher, and while exploring it may reveal the location of a hidden lair.',effect:{stat:'sage',bonus:1},tier:1},
  // ── Spy ──
  {name:'Shadowcloak',desc:'Spy +2',lore:'A cloak the colour of dusk that swallows footsteps and turns eyes aside. Spy skill counts as 2 levels higher.',effect:{stat:'spy',bonus:2},tier:2},
  {name:'Crystal Orb',desc:'Spy always succeeds — no roll needed',lore:'A flawless sphere in which distant halls and whispered councils appear at a thought. A LEGENDARY relic: every Spy order you give succeeds automatically, with no roll needed.',effect:{stat:'oracle',bonus:1},tier:3},
  {name:'Whispering Mirror',desc:'Spy +1',lore:'Gaze into it long enough and faint voices from far away begin to speak. Spy skill counts 1 level higher.',effect:{stat:'spy',bonus:1},tier:1},
  // ── Thief ──
  {name:'Gloves of the Nightcrawler',desc:'Thief +2',lore:'Soft black gloves that leave no print, catch no latch and never fumble a lock. Thief skill counts as 2 levels higher.',effect:{stat:'thief',bonus:2},tier:2},
  {name:'Lock-Pick of Legends',desc:'Thief +1, +20% steal chance in encounters',lore:'No strongbox in the world has yet resisted it. Thief skill counts 1 level higher, and your chance to steal in an encounter is +20%.',effect:{stat:'thief',bonus:1},tier:1},
  // ── Druid ──
  {name:'Staff of the Wildwood',desc:'Druid +2',lore:'Living wood, still budding in spring, that beasts and monsters instinctively defer to. Druid skill counts as 2 levels higher.',effect:{stat:'druid',bonus:2},tier:2},
  {name:'Beastcaller\'s Warhorn',desc:'Druid +1, and the pre-battle strikes of primal and special armies you lead fire +15% more often',lore:'A curved horn of aurochs bone, its note pitched for beasts rather than men. Druid skill counts 1 level higher, and the pre-battle strikes (Boulder Barrage, Choking Spores, Dragonfire Breath and the like) of primal and special armies you lead fire 15% more often.',effect:{stat:'druid',bonus:1},primalStrike:15,tier:1},
  {name:'Totem of the Thunderhead',desc:'Pre-battle strikes of primal and special armies you lead fire +25% more often',lore:'A carved storm-spirit on a pole, hung with feathers and teeth; the wild things watch it for their signal. The pre-battle strikes of every primal and special army you lead fire 25% more often.',effect:{stat:'primalStrike',bonus:25},tier:2},
  {name:'Green Stone of Speaking',desc:'Druid +1',lore:'A smooth green gem through which the speech of beasts becomes plain. Druid skill counts 1 level higher.',effect:{stat:'druid',bonus:1},tier:1},
  // ── Explorer ──
  {name:'Ring of the Explorer',desc:'Explorer +2',lore:'Worn by a wanderer who walked the whole known world and half the unknown one. Explorer skill counts as 2 levels higher, so you chart more of every province.',effect:{stat:'explorer',bonus:2},tier:2},
  {name:'Compass of the Wanderer',desc:'Explorer +1',lore:'Its needle points not north but towards whatever is worth finding. Explorer skill counts 1 level higher.',effect:{stat:'explorer',bonus:1},tier:1},
  // ── White Magic ──
  {name:'Holy Reliquary',desc:'White Magic +2',lore:'A gilded casket holding some fragment of a saint; prayers spoken over it are answered more readily. White Magic skill counts as 2 levels higher.',effect:{stat:'white',bonus:2},tier:2},
  {name:'Chalice of Dawn',desc:'White Magic +1; if your realm is Divine, all armies you lead fight at +15%',lore:'Light seems to pool in this cup even at midnight. White Magic skill counts 1 level higher, and if your realm is Divine every army you lead fights at +15%.',effect:{stat:'white',bonus:1},tier:1},
  // ── Psychic Magic ──
  {name:'Mind\'s Eye Amulet',desc:'Psychic Magic +2',lore:'A pendant carved with a single open eye; the thoughts of others drift towards its wearer. Psychic Magic skill counts as 2 levels higher.',effect:{stat:'psychic',bonus:2},tier:2},
  {name:'Dreamstone',desc:'Psychic Magic +1, and your Psychic Blast in personal combat stuns for an extra round',lore:'A dull grey stone that hums at the edge of hearing and leaves foes reeling. Psychic Magic skill counts 1 level higher, and your Psychic Blast in personal combat stuns for an extra round.',effect:{stat:'psychic',bonus:1},tier:1},
  // ── Illusory Magic ──
  {name:'Veil of Illusions',desc:'Illusory Magic +2',lore:'Gossamer that shifts colour as you watch; the world around its wearer is never quite what it seems. Illusory Magic skill counts as 2 levels higher.',effect:{stat:'illusory',bonus:2},tier:2},
  {name:'Mirror Shard',desc:'Illusory Magic +1, and your Mirror Image illusions are harder to disbelieve',lore:'A splinter of a mirror that shows what you wish were true. Illusory Magic skill counts 1 level higher, and your Mirror Image illusions are harder for an enemy to disbelieve.',effect:{stat:'illusory',bonus:1},tier:1},
  // ── Elemental Magic ──
  {name:'Orb of the Storm',desc:'Elemental Magic +2',lore:'A glass sphere with a thunderhead forever turning inside it. Elemental Magic skill counts as 2 levels higher.',effect:{stat:'elemental',bonus:2},tier:2},
  {name:'Ember Rune',desc:'Elemental Magic +1, and your Fireball strikes the two strongest enemy units instead of one',lore:'A rune-stone that stays warm to the touch and spits sparks when angered. Elemental Magic skill counts 1 level higher, and your Fireball in battle strikes the two strongest enemy units instead of one.',effect:{stat:'elemental',bonus:1},emberTwo:true,tier:1},
  // ── Necromancy ──
  {name:'Skull of the Undying',desc:'Necromancy +2',lore:'A grinning skull that whispers the names of the dead to whoever holds it. Necromancy skill counts as 2 levels higher.',effect:{stat:'necromancy',bonus:2},tier:2},
  {name:'Death\'s Finger Ring',desc:'Necromancy +1, and your Hand of Death does 10% more damage in personal combat',lore:'A ring of pale bone that chills the hand it sits on. Necromancy skill counts 1 level higher, and your Hand of Death in personal combat deals 10% more damage.',effect:{stat:'necromancy',bonus:1},tier:1},
  // ── HP ──
  {name:'Amulet of Fortitude',desc:'Max HP +8',lore:'The wearer\'s wounds close faster and their heart beats stronger. Maximum HP +8.',effect:{stat:'maxHp',bonus:8},tier:2},
  {name:'Iron Heart Talisman',desc:'Max HP +5, +10% HP recovered each Rest order',lore:'Cold iron worn against the chest steadies the pulse and hardens the body. Maximum HP +5, and each Rest order recovers 10% more HP.',effect:{stat:'maxHp',bonus:5},tier:1},
  // ── Army bonuses (general) ──
  {name:'Battle Standard',desc:'All armies led: strength +2 each',lore:'The banner of a forgotten legion, under which no soldier ever broke. A LEGENDARY relic: every army you lead fights at +2 strength.',effect:{stat:'armyBonus',bonus:2},tier:3},
  {name:'Banner of the Realm',desc:'All armies led: +1 quality tier when defending home province',lore:'A banner bearing the old arms of the crown; folk fight like lions beneath it on their own soil. Every army you lead fights one quality tier higher when defending your home province.',effect:{stat:'homeDefBonus',bonus:1},tier:2},
  // ── Cavalry-specific (Free Lances / Gilded Lances) ──
  {name:'Golden Spur',desc:'Free Lances and Gilded Lances: +25% strength when you lead them',lore:'A single gilded spur once worn by a legendary captain of horse. Free Lances and Gilded Lances you lead fight at +25% strength.',effect:{stat:'cavBonus',bonus:1},tier:1},
  {name:'War-Horn of the Plains',desc:'Free Lances you lead always ride a broken enemy down — in any terrain, at the full pursuit bonus',lore:'One blast and the horses will not be held. Free Lances you lead always ride down a broken enemy — in any terrain, at the full pursuit bonus.',effect:{stat:'cavPursuit',bonus:1},tier:1},
  // ── Infantry-specific (Shieldwall Levies) ──
  {name:'Legionnaire\'s Mark',desc:'Shieldwall Levies you lead: +20% strength in all terrain',lore:'A brass badge of the old legions, and the foot who see it stand a little straighter. Shieldwall Levies you lead fight at +20% strength in every terrain.',effect:{stat:'infBonus',bonus:1},tier:1},
  {name:'Shield-Wall Rune',desc:'Shieldwall Levies you lead never retreat from a losing battle (stay and fight)',lore:'A rune of the unbroken line painted on the innermost shield. Shieldwall Levies you lead never retreat from a losing battle; they stay and fight.',effect:{stat:'infStay',bonus:1},tier:1},
  // ── Archer-specific ──
  {name:'Quiver of Many Arrows',desc:'Archer units you lead: fire one extra shot in the archery pre-phase',lore:'However many arrows are drawn from it there is always one more. Every archer unit you lead fires one extra shot in the pre-battle archery phase.',effect:{stat:'archBonus',bonus:1},tier:1},
  {name:'Eagle-Eye Pendant',desc:'Yeoman Longbows and Elven Bowmen: +30% strength',lore:'The wearer\'s archers seem to see the foe a heartbeat before he sees them. Yeoman Longbows and Elven Bowmen you lead fight at +30% strength.',effect:{stat:'archerStr',bonus:1},tier:1},
  // ── Naval-specific ──
  {name:'Kraken Figurehead',desc:'All fleets you lead fight as if one experience level higher',lore:'Carved from a beast that dragged whole fleets under; sailors under it fight like they have been at sea all their lives. A LEGENDARY relic: every fleet you lead fights one experience level higher.',effect:{stat:'navalBonus',bonus:1},tier:3},
  {name:'Tide-Caller\'s Horn',desc:'Land units you lead fight at full battle strength in sea battles',lore:'A conch that calms the swell beneath your soldiers\' feet. Land units you lead fight at full strength in sea battles instead of the usual penalty.',effect:{stat:'navalMove',bonus:1},landFullAtSea:true,tier:2},
  // ── Heavy/Siege-specific ──
  {name:'Engineer\'s Blueprint',desc:'Mountain Guns and Dwarf Ironclads: +4 strength',lore:'Schematics for guns and hulls beyond anything the guild-smiths have built. Mountain Guns and Dwarf Ironclads you lead fight at +4 strength.',effect:{stat:'heavyBonus',bonus:1},tier:1},
  {name:'Siege Master\'s Ring',desc:'Province defence bonuses reduced by half when you attack',lore:'The signet of the engineer who cracked the Ninefold Gate. When you attack, the defenders\' province and fortification bonuses are halved.',effect:{stat:'siegeBonus',bonus:1},tier:2},
  // ── Undead-specific ──
  {name:'Black Sceptre',desc:'Skeletal Legions you lead: +4 strength',lore:'A rod of black iron topped with a skull; the dead march straighter when it is raised. Skeletal Legions you lead fight at +4 strength.',effect:{stat:'undeadBonus',bonus:1},tier:1},
  // ── SPELL ITEMS: two per castable action spell. Use Item casts the spell as a phase order at a
  // flat 95%, no skill or casting-slot needed (effects scale as if caster level 3, or the holder's
  // own level if higher). Mastery-spell items are tier 2 (tier 3 stays the ten Relics).
  {name:'Phial of the Dawn',desc:'Use Item: casts Resurrect (white) as a phase order at 95%, whatever your skill.',lore:'A stoppered phial holding one drop of the first light. Use Item: casts Resurrect as a phase order at 95%, whatever your White Magic skill.',effect:{stat:'castSpell',spell:'Resurrect',bonus:0},tier:1},
  {name:'Saint\'s Knucklebone',desc:'Use Item: casts Resurrect (white) as a phase order at 95%, whatever your skill.',lore:'A small bone in a silver reliquary, warm to the touch. Use Item: casts Resurrect as a phase order at 95%, whatever your White Magic skill.',effect:{stat:'castSpell',spell:'Resurrect',bonus:0},tier:1},
  {name:'Rod of the Parted Waters',desc:'Use Item: casts Part Sea (white) as a phase order at 95%, whatever your skill.',lore:'A staff that once split a sea for a fleeing people. Use Item: casts Part Sea as a phase order at 95%, whatever your White Magic skill.',effect:{stat:'castSpell',spell:'Part Sea',bonus:0},tier:1},
  {name:'Pilgrim\'s Sandal',desc:'Use Item: casts Part Sea (white) as a phase order at 95%, whatever your skill.',lore:'One worn sandal that walked dry-shod across a strait. Use Item: casts Part Sea as a phase order at 95%, whatever your White Magic skill.',effect:{stat:'castSpell',spell:'Part Sea',bonus:0},tier:1},
  {name:'Censer of Plenty',desc:'Use Item: casts Bless Province (white) as a phase order at 95%, whatever your skill.',lore:'Sweet smoke from this censer makes the fields heavy with grain. Use Item: casts Bless Province as a phase order at 95%, whatever your White Magic skill.',effect:{stat:'castSpell',spell:'Bless Province',bonus:0},tier:1},
  {name:'Harvest Icon',desc:'Use Item: casts Bless Province (white) as a phase order at 95%, whatever your skill.',lore:'A painted panel of a saint holding a sheaf of wheat. Use Item: casts Bless Province as a phase order at 95%, whatever your White Magic skill.',effect:{stat:'castSpell',spell:'Bless Province',bonus:0},tier:1},
  {name:'Locket of Sweet Words',desc:'Use Item: casts Charm (psychic) as a phase order at 95%, whatever your skill.',lore:'Open it and everyone nearby seems to like you a little better. Use Item: casts Charm as a phase order at 95%, whatever your Psychic Magic skill.',effect:{stat:'castSpell',spell:'Charm',bonus:0},tier:1},
  {name:'Silver Tongue Charm',desc:'Use Item: casts Charm (psychic) as a phase order at 95%, whatever your skill.',lore:'A tiny silver tongue on a chain; its wearer is very hard to refuse. Use Item: casts Charm as a phase order at 95%, whatever your Psychic Magic skill.',effect:{stat:'castSpell',spell:'Charm',bonus:0},tier:1},
  {name:'Speaker\'s Laurel',desc:'Use Item: casts Oratory (psychic) as a phase order at 95%, whatever your skill.',lore:'A wreath worn by the orators of the old Senate. Use Item: casts Oratory as a phase order at 95%, whatever your Psychic Magic skill.',effect:{stat:'castSpell',spell:'Oratory',bonus:0},tier:1},
  {name:'Horn of the Assembly',desc:'Use Item: casts Oratory (psychic) as a phase order at 95%, whatever your skill.',lore:'Its note carries every word to the back of the crowd. Use Item: casts Oratory as a phase order at 95%, whatever your Psychic Magic skill.',effect:{stat:'castSpell',spell:'Oratory',bonus:0},tier:1},
  {name:'Seer\'s Bowl',desc:'Use Item: casts Clairvoyance (psychic) as a phase order at 95%, whatever your skill.',lore:'Fill it with water and distant places swim into view. Use Item: casts Clairvoyance as a phase order at 95%, whatever your Psychic Magic skill.',effect:{stat:'castSpell',spell:'Clairvoyance',bonus:0},tier:1},
  {name:'Eye of the Far Watch',desc:'Use Item: casts Clairvoyance (psychic) as a phase order at 95%, whatever your skill.',lore:'A glass eye that sees for miles. Use Item: casts Clairvoyance as a phase order at 95%, whatever your Psychic Magic skill.',effect:{stat:'castSpell',spell:'Clairvoyance',bonus:0},tier:1},
  {name:'Shard of the Screaming Mind',desc:'Use Item: casts Psychic Blast (psychic) as a phase order at 95%, whatever your skill.',lore:'A crystal that shrieks inside the skull of anyone it is turned upon. Use Item: casts Psychic Blast as a phase order at 95%, whatever your Psychic Magic skill.',effect:{stat:'castSpell',spell:'Psychic Blast',bonus:0},tier:1},
  {name:'Migraine Stone',desc:'Use Item: casts Psychic Blast (psychic) as a phase order at 95%, whatever your skill.',lore:'A dull stone that brings a blinding headache to the one it is pointed at. Use Item: casts Psychic Blast as a phase order at 95%, whatever your Psychic Magic skill.',effect:{stat:'castSpell',spell:'Psychic Blast',bonus:0},tier:1},
  {name:'Whirlwind Bracelet',desc:'Use Item: casts Telekinetic Storm (psychic) as a phase order at 95%, whatever your skill.',lore:'Twist it and the air itself picks up and throws. Use Item: casts Telekinetic Storm as a phase order at 95%, whatever your Psychic Magic skill.',effect:{stat:'castSpell',spell:'Telekinetic Storm',bonus:0},tier:1},
  {name:'Gauntlet of the Unseen Hand',desc:'Use Item: casts Telekinetic Storm (psychic) as a phase order at 95%, whatever your skill.',lore:'Close the fist and things far away are crushed. Use Item: casts Telekinetic Storm as a phase order at 95%, whatever your Psychic Magic skill.',effect:{stat:'castSpell',spell:'Telekinetic Storm',bonus:0},tier:1},
  {name:'Cartographer\'s Prism',desc:'Use Item: casts Illusory Terrain (illusory) as a phase order at 95%, whatever your skill.',lore:'Held to the eye it bends the land into whatever shape you please. Use Item: casts Illusory Terrain as a phase order at 95%, whatever your Illusory Magic skill.',effect:{stat:'castSpell',spell:'Illusory Terrain',bonus:0},tier:1},
  {name:'Mirage Glass',desc:'Use Item: casts Illusory Terrain (illusory) as a phase order at 95%, whatever your skill.',lore:'A pane of desert glass in which hills become plains and plains become swamps. Use Item: casts Illusory Terrain as a phase order at 95%, whatever your Illusory Magic skill.',effect:{stat:'castSpell',spell:'Illusory Terrain',bonus:0},tier:1},
  {name:'Banner of Shadows',desc:'Use Item: casts Phantasmal Armies (illusory) as a phase order at 95%, whatever your skill.',lore:'Raise it and a host of shadows falls in behind your ranks. Use Item: casts Phantasmal Armies as a phase order at 95%, whatever your Illusory Magic skill.',effect:{stat:'castSpell',spell:'Phantasmal Armies',bonus:0},tier:1},
  {name:'Drum of Ten Thousand',desc:'Use Item: casts Phantasmal Armies (illusory) as a phase order at 95%, whatever your skill.',lore:'Its beat sounds like ten thousand marching feet. Use Item: casts Phantasmal Armies as a phase order at 95%, whatever your Illusory Magic skill.',effect:{stat:'castSpell',spell:'Phantasmal Armies',bonus:0},tier:1},
  {name:'Fogbinder\'s Lantern',desc:'Use Item: casts Hide Lairs (illusory) as a phase order at 95%, whatever your skill.',lore:'It casts not light but a concealing mist. Use Item: casts Hide Lairs as a phase order at 95%, whatever your Illusory Magic skill.',effect:{stat:'castSpell',spell:'Hide Lairs',bonus:0},tier:1},
  {name:'Moth-Wing Veil',desc:'Use Item: casts Hide Lairs (illusory) as a phase order at 95%, whatever your skill.',lore:'Grey and dusty, it makes things beneath it easy to overlook. Use Item: casts Hide Lairs as a phase order at 95%, whatever your Illusory Magic skill.',effect:{stat:'castSpell',spell:'Hide Lairs',bonus:0},tier:1},
  {name:'Ring of Vanishing',desc:'Use Item: casts Invisibility (illusory) as a phase order at 95%, whatever your skill.',lore:'Turn it and you are simply not there. Use Item: casts Invisibility as a phase order at 95%, whatever your Illusory Magic skill.',effect:{stat:'castSpell',spell:'Invisibility',bonus:0},tier:1},
  {name:'Hood of No-Face',desc:'Use Item: casts Invisibility (illusory) as a phase order at 95%, whatever your skill.',lore:'Pull it up and no eye can settle on you. Use Item: casts Invisibility as a phase order at 95%, whatever your Illusory Magic skill.',effect:{stat:'castSpell',spell:'Invisibility',bonus:0},tier:1},
  {name:'Hammer of the Deep Root',desc:'Use Item: casts Earthquake (elemental) as a phase order at 95%, whatever your skill.',lore:'Strike the ground and the ground answers. Use Item: casts Earthquake as a phase order at 95%, whatever your Elemental Magic skill.',effect:{stat:'castSpell',spell:'Earthquake',bonus:0},tier:1},
  {name:'Fault-Stone',desc:'Use Item: casts Earthquake (elemental) as a phase order at 95%, whatever your skill.',lore:'A cracked stone that shakes the earth where it is thrown. Use Item: casts Earthquake as a phase order at 95%, whatever your Elemental Magic skill.',effect:{stat:'castSpell',spell:'Earthquake',bonus:0},tier:1},
  {name:'Conch of the Drowned Bell',desc:'Use Item: casts Flood (elemental) as a phase order at 95%, whatever your skill.',lore:'Blow it and the waters rise. Use Item: casts Flood as a phase order at 95%, whatever your Elemental Magic skill.',effect:{stat:'castSpell',spell:'Flood',bonus:0},tier:1},
  {name:'Tide-Warden\'s Urn',desc:'Use Item: casts Flood (elemental) as a phase order at 95%, whatever your skill.',lore:'Pour it out and it never runs dry. Use Item: casts Flood as a phase order at 95%, whatever your Elemental Magic skill.',effect:{stat:'castSpell',spell:'Flood',bonus:0},tier:1},
  {name:'Elementalist\'s Brazier',desc:'Use Item: casts Elemental Summon (elemental) as a phase order at 95%, whatever your skill.',lore:'Coals that call spirits of flame, stone and storm to your side. Use Item: casts Elemental Summon as a phase order at 95%, whatever your Elemental Magic skill.',effect:{stat:'castSpell',spell:'Elemental Summon',bonus:0},tier:1},
  {name:'Four-Wind Compass',desc:'Use Item: casts Elemental Summon (elemental) as a phase order at 95%, whatever your skill.',lore:'Its four needles each point to an elemental power. Use Item: casts Elemental Summon as a phase order at 95%, whatever your Elemental Magic skill.',effect:{stat:'castSpell',spell:'Elemental Summon',bonus:0},tier:1},
  {name:'Leash of Bone',desc:'Use Item: casts Control Undead (necromancy) as a phase order at 95%, whatever your skill.',lore:'A cord of knotted vertebrae that the dead obey. Use Item: casts Control Undead as a phase order at 95%, whatever your Necromancy skill.',effect:{stat:'castSpell',spell:'Control Undead',bonus:0},tier:1},
  {name:'Grave-Warden\'s Whistle',desc:'Use Item: casts Control Undead (necromancy) as a phase order at 95%, whatever your skill.',lore:'One shrill note and the walking dead turn to heel. Use Item: casts Control Undead as a phase order at 95%, whatever your Necromancy skill.',effect:{stat:'castSpell',spell:'Control Undead',bonus:0},tier:1},
  {name:'Reaper\'s Bell',desc:'Use Item: casts Skeletal Armies (necromancy) as a phase order at 95%, whatever your skill.',lore:'Its toll calls the fallen up from their graves. Use Item: casts Skeletal Armies as a phase order at 95%, whatever your Necromancy skill.',effect:{stat:'castSpell',spell:'Skeletal Armies',bonus:0},tier:1},
  {name:'Ossuary Key',desc:'Use Item: casts Skeletal Armies (necromancy) as a phase order at 95%, whatever your skill.',lore:'It opens every tomb at once. Use Item: casts Skeletal Armies as a phase order at 95%, whatever your Necromancy skill.',effect:{stat:'castSpell',spell:'Skeletal Armies',bonus:0},tier:1},
  {name:'Hexwright\'s Needle',desc:'Use Item: casts Curse (necromancy) as a phase order at 95%, whatever your skill.',lore:'Prick a name with it and ill luck follows. Use Item: casts Curse as a phase order at 95%, whatever your Necromancy skill.',effect:{stat:'castSpell',spell:'Curse',bonus:0},tier:1},
  {name:'Blackened Wishbone',desc:'Use Item: casts Curse (necromancy) as a phase order at 95%, whatever your skill.',lore:'Snap it while naming an enemy. Use Item: casts Curse as a phase order at 95%, whatever your Necromancy skill.',effect:{stat:'castSpell',spell:'Curse',bonus:0},tier:1},
  {name:'Vial of the Weeping Rot',desc:'Use Item: casts Plague (necromancy) as a phase order at 95%, whatever your skill.',lore:'Uncork it upwind of a town. Use Item: casts Plague as a phase order at 95%, whatever your Necromancy skill.',effect:{stat:'castSpell',spell:'Plague',bonus:0},tier:1},
  {name:'Rat-King\'s Crown',desc:'Use Item: casts Plague (necromancy) as a phase order at 95%, whatever your skill.',lore:'A crown of knotted tails; vermin swarm wherever it is set down. Use Item: casts Plague as a phase order at 95%, whatever your Necromancy skill.',effect:{stat:'castSpell',spell:'Plague',bonus:0},tier:1},
  // the twenty tier-2 items that cast the ten MASTERY spells (Sanctuary, Divine Judgment, Mass
  // Confusion, Dominate, Phantom Host, Veil, Chain Lightning, Cataclysm, Raise Wraiths, Death's
  // Dominion) are REMOVED — level 7/9 spells come only from earning the skill. Any such item still
  // held from an older save is inert: the cast handler refuses item-casts of mastery spells.
  {name:'Wailing Phylactery',desc:'Necromancy spells always succeed first cast per turn',lore:'A sealed jar in which something still screams; death-magic worked near it never falters. A LEGENDARY relic: the first Necromancy spell you cast each turn succeeds automatically.',effect:{stat:'necroAuto',bonus:1},tier:3},
  // ── TEMPER ITEMS: while EQUIPPED, the wearer fights, flees, duels and begs mercy
  // with the item's temper instead of their own (personal combat, duel stances, NPC auto-plans). Two
  // per temper; all occupy a slot so they compete with other worn items. Tier 1. ──
  {name:'Warmask of the Red Rage',desc:'While equipped your temper becomes Berserk in all personal combat.',lore:'A snarling war-mask; whoever wears it sees only red. While equipped your temper is Berserk in all personal combat.',effect:{stat:'temper',temper:'Berserk',bonus:0},slot:'helm',tier:1},
  {name:'Bloodstone Torc',desc:'While equipped your temper becomes Berserk in all personal combat.',lore:'A neck-ring set with a stone the colour of fresh blood that sets the heart pounding. While equipped your temper is Berserk in all personal combat.',effect:{stat:'temper',temper:'Berserk',bonus:0},slot:'amulet',tier:1},
  {name:'Lionheart Pendant',desc:'While equipped your temper becomes Brave in all personal combat.',lore:'Worn over the heart, it drives out fear and leaves only resolve. While equipped your temper is Brave in all personal combat.',effect:{stat:'temper',temper:'Brave',bonus:0},slot:'amulet',tier:1},
  {name:'Circlet of Valour',desc:'While equipped your temper becomes Brave in all personal combat.',lore:'A plain band that steadies the nerve when steel is drawn. While equipped your temper is Brave in all personal combat.',effect:{stat:'temper',temper:'Brave',bonus:0},slot:'helm',tier:1},
  {name:'Ring of Second Thoughts',desc:'While equipped your temper becomes Cautious in all personal combat.',lore:'It nags at its wearer to look before leaping. While equipped your temper is Cautious in all personal combat.',effect:{stat:'temper',temper:'Cautious',bonus:0},slot:'ring',tier:1},
  {name:'Cloak of Measured Steps',desc:'While equipped your temper becomes Cautious in all personal combat.',lore:'Under this cloak no move is made in haste. While equipped your temper is Cautious in all personal combat.',effect:{stat:'temper',temper:'Cautious',bonus:0},slot:'cloak',tier:1},
  {name:'Hare-Foot Charm',desc:'While equipped your temper becomes Cowardly in all personal combat.',lore:'A lucky rabbit\'s foot with a strong urge to run attached. While equipped your temper is Cowardly in all personal combat.',effect:{stat:'temper',temper:'Cowardly',bonus:0},slot:'ring',tier:1},
  {name:'Craven\'s Amulet',desc:'While equipped your temper becomes Cowardly in all personal combat.',lore:'Its wearer suddenly remembers urgent business elsewhere. While equipped your temper is Cowardly in all personal combat.',effect:{stat:'temper',temper:'Cowardly',bonus:0},slot:'amulet',tier:1},

  // ── COMBAT-USE ITEMS: potions, scrolls and devices used IN PERSONAL COMBAT. Each fires
  // ONCE per combat, is never consumed, costs the user's action that round, and is used only when it makes
  // sense (healing when hurt, banes against the right foe, wards before the pain...). Guardians that can
  // wield lair items use them too. `use` decides trigger + effect (see pcCombatItemPlan / pcUseCombatItem). ──
  {name:'Potion of Healing',desc:'Combat use: drink to recover 8 HP once per fight (used when below half health).',lore:'A red draught that knits flesh as it goes down. Used once per personal combat when you fall below half health: recover 8 HP.',effect:{stat:'combatUse',use:'heal',amt:8,below:0.5,bonus:0},tier:1},
  {name:'Elixir of Vigour',desc:'Combat use: drink to recover 15 HP once per fight (used when below 40% health).',lore:'A golden tonic that puts new strength in tired limbs. Used once per personal combat when you fall below 40% health: recover 15 HP.',effect:{stat:'combatUse',use:'heal',amt:15,below:0.4,bonus:0},tier:2},
  {name:'Salve of Closing Wounds',desc:'Combat use: recover 5 HP once per fight (used when below 60% health).',lore:'A field surgeon\'s balm, smeared on in the thick of the fight. Used once per personal combat when below 60% health: recover 5 HP.',effect:{stat:'combatUse',use:'heal',amt:5,below:0.6,bonus:0},tier:1},
  {name:'Draught of the Phoenix',desc:'Combat use: recover 20 HP once per fight (used only when below 30% health).',lore:'Ashes and fire in a phial; it brings the near-dead back to their feet. Used once per personal combat, only when below 30% health: recover 20 HP.',effect:{stat:'combatUse',use:'heal',amt:20,below:0.3,bonus:0},tier:2},
  {name:'Potion of Regeneration',desc:'Combat use: heal 3 HP at the start of each of the next 4 rounds (used when below 70% health).',lore:'A tincture that keeps working long after it is swallowed. Used once per personal combat when below 70% health: heal 3 HP at the start of each of the next 4 rounds.',effect:{stat:'combatUse',use:'hot',amt:3,rounds:4,below:0.7,bonus:0},tier:1},
  {name:'Elixir of Second Wind',desc:'Combat use: recover 10 HP and shake off every lingering poison and curse (used when hurt and afflicted).',lore:'Clears the blood and clears the head. Used once per personal combat when hurt and afflicted: recover 10 HP and shake off every lingering poison and curse.',effect:{stat:'combatUse',use:'secondwind',amt:10,below:0.6,bonus:0},tier:2},
  {name:'Scroll of Fire',desc:'Combat use: a gout of flame for 8-14 damage, once per fight.',lore:'Read it aloud and a gout of flame leaps from the page. Used once per personal combat: 8-14 fire damage to your foe.',effect:{stat:'combatUse',use:'dmg',dmg:[8,14],bonus:0},tier:1},
  {name:'Scroll of Frost',desc:'Combat use: a killing cold for 6-10 damage and -15% to the foe\'s aim, once per fight.',lore:'The words freeze in the air as they are spoken. Used once per personal combat: 6-10 damage, and the foe\'s aim suffers -15% to hit.',effect:{stat:'combatUse',use:'dmg',dmg:[6,10],hitPen:15,bonus:0},tier:1},
  {name:'Scroll of Lightning',desc:'Combat use: a lightning stroke for 10-16 damage, once per fight.',lore:'The script crackles as it is read. Used once per personal combat: a lightning stroke for 10-16 damage.',effect:{stat:'combatUse',use:'dmg',dmg:[10,16],bonus:0},tier:2},
  {name:'Scroll of Acid',desc:'Combat use: a spray of acid for 5-9 damage that burns for 3 more each round for 2 rounds.',lore:'The ink itself is caustic. Used once per personal combat: 5-9 damage, then the acid burns for 3 more each round for 2 rounds.',effect:{stat:'combatUse',use:'dmg',dmg:[5,9],dot:[3,2],bonus:0},tier:1},
  {name:'Wand of Sparks',desc:'Combat use: a crackle of sparks for 4-8 damage, once per fight.',lore:'A short rod that throws a crackling burst. Used once per personal combat: 4-8 damage.',effect:{stat:'combatUse',use:'dmg',dmg:[4,8],bonus:0},tier:1},
  {name:'Scroll of Shadow Bolt',desc:'Combat use: a bolt of darkness for 7-12 damage, once per fight.',lore:'Words written in something darker than ink. Used once per personal combat: a bolt of darkness for 7-12 damage.',effect:{stat:'combatUse',use:'dmg',dmg:[7,12],bonus:0},tier:1},
  {name:'Vial of Alchemist\'s Fire',desc:'Combat use: hurled fire for 6-11 damage that keeps burning for 2 each round for 2 rounds.',lore:'Hurl it and it clings and burns. Used once per personal combat: 6-11 damage, then 2 more each round for 2 rounds.',effect:{stat:'combatUse',use:'dmg',dmg:[6,11],dot:[2,2],bonus:0},tier:1},
  {name:'Scroll of Sunburst',desc:'Combat use: searing light for 8-14 damage, doubled against undead and fiends.',lore:'A prayer that flares like noon. Used once per personal combat: 8-14 damage, doubled against undead and fiends.',effect:{stat:'combatUse',use:'dmg',dmg:[8,14],doubleVs:['undead','fiend'],bonus:0},tier:2},
  {name:'Thunder Stone',desc:'Combat use: a deafening crack for 5-9 damage that costs the foe their next action.',lore:'Throw it down and the crack leaves the foe stunned. Used once per personal combat: 5-9 damage and the foe loses their next action.',effect:{stat:'combatUse',use:'dmg',dmg:[5,9],stun:1,bonus:0},tier:1},
  {name:'Scroll of Twin Bolts',desc:'Combat use: two bolts of force, each 3-6 damage, once per fight.',lore:'Two bolts of force from one page. Used once per personal combat: two hits of 3-6 damage each.',effect:{stat:'combatUse',use:'dmg',dmg:[3,6],times:2,bonus:0},tier:1},
  {name:'Scroll of Paralysis',desc:'Combat use: the foe is frozen in place and loses their next 2 actions.',lore:'The foe locks rigid mid-stride. Used once per personal combat: the foe loses their next 2 actions.',effect:{stat:'combatUse',use:'stun',stun:2,bonus:0},tier:2},
  {name:'Scroll of Sleep',desc:'Combat use: the foe nods off and loses their next action.',lore:'A lullaby in a dead tongue. Used once per personal combat: the foe nods off and loses their next action.',effect:{stat:'combatUse',use:'stun',stun:1,bonus:0},tier:1},
  {name:'Scroll of Blindness',desc:'Combat use: the foe is blinded, -25% to hit (fades 5% per round).',lore:'A flash the foe cannot blink away. Used once per personal combat: the foe suffers -25% to hit, fading 5% per round.',effect:{stat:'combatUse',use:'pen',hitPen:25,bonus:0},tier:1},
  {name:'Scroll of Confusion',desc:'Combat use: the foe\'s wits scatter, -30% to hit (fades 5% per round).',lore:'The foe forgets which end of the sword to hold. Used once per personal combat: the foe suffers -30% to hit, fading 5% per round.',effect:{stat:'combatUse',use:'pen',hitPen:30,bonus:0},tier:2},
  {name:'Scroll of Weakness',desc:'Combat use: the foe\'s arm goes leaden — Melee -1 for the rest of the fight.',lore:'The foe\'s sword-arm turns to lead. Used once per personal combat: the foe\'s Melee counts 1 lower for the rest of the fight.',effect:{stat:'combatUse',use:'weak',melee:1,bonus:0},tier:1},
  {name:'Scroll of Curse',desc:'Combat use: the foe suffers Melee -1 and Archery -1 for the rest of the fight.',lore:'A malediction that saps the whole body. Used once per personal combat: the foe\'s Melee and Archery each count 1 lower for the rest of the fight.',effect:{stat:'combatUse',use:'weak',melee:1,archery:1,bonus:0},tier:2},
  {name:'Scroll of Terror',desc:'Combat use: a living foe must steel their nerve or flee; the fearless are shaken (-15% to hit) instead.',lore:'A nameless dread pours off the page. Used once per personal combat: a living foe must steel their nerve or flee; the fearless are merely shaken, at -15% to hit.',effect:{stat:'combatUse',use:'terror',hitPen:15,bonus:0},tier:1},
  {name:'Bolas of Binding',desc:'Combat use: the foe is tangled and loses their next action.',lore:'Weighted cords that tangle a foe\'s legs. Used once per personal combat: the foe loses their next action.',effect:{stat:'combatUse',use:'stun',stun:1,bonus:0},tier:1},
  {name:'Scroll of Silence',desc:'Combat use: the foe\'s magic and special powers are bound for 3 rounds (used only against casters and monsters with powers).',lore:'The words swallow every other word. Used once per personal combat, only against casters and monsters with special powers: the foe\'s magic and powers are bound for 3 rounds.',effect:{stat:'combatUse',use:'silence',rounds:3,bonus:0},tier:1},
  {name:'Potion of Strength',desc:'Combat use: Melee +1 for the rest of the fight (drunk as the fight opens).',lore:'Ox-blood and iron filings; the arm swells with power. Drunk as a personal combat opens: Melee counts 1 higher for the rest of the fight.',effect:{stat:'combatUse',use:'buff',melee:1,bonus:0},tier:1},
  {name:'Potion of Giant\'s Might',desc:'Combat use: Melee +2 for the rest of the fight (drunk as the fight opens).',lore:'Brewed from something very large. Drunk as a personal combat opens: Melee counts 2 higher for the rest of the fight.',effect:{stat:'combatUse',use:'buff',melee:2,bonus:0},tier:2},
  {name:'Potion of Heroism',desc:'Combat use: Melee +1 and Archery +1 for the rest of the fight.',lore:'A cordial that makes champions of ordinary soldiers. Drunk as a personal combat opens: Melee and Archery each count 1 higher for the rest of the fight.',effect:{stat:'combatUse',use:'buff',melee:1,archery:1,bonus:0},tier:1},
  {name:'Elixir of Focus',desc:'Combat use: +10% to hit for the rest of the fight (drunk as the fight opens).',lore:'The world slows and every opening is plain. Drunk as a personal combat opens: +10% to hit for the rest of the fight.',effect:{stat:'combatUse',use:'focus',hitBonus:10,bonus:0},tier:1},
  {name:'Potion of Iron Skin',desc:'Combat use: a ward that soaks the next 10 damage taken (used when first hurt).',lore:'The skin hardens like the anvil it was brewed on. Used once per personal combat when first hurt: a ward that soaks the next 10 damage you would take.',effect:{stat:'combatUse',use:'absorb',absorb:10,bonus:0},tier:1},
  {name:'Scroll of Ward',desc:'Combat use: a shimmering ward that soaks 8 damage and bites back for 2 on every hit against you.',lore:'A glyph that turns harm back on the hand that dealt it. Used once per personal combat: a shimmering ward that soaks 8 damage and deals 2 damage back on every hit against you.',effect:{stat:'combatUse',use:'absorb',absorb:8,reflect:2,bonus:0},tier:2},
  {name:'Scroll of Stone Skin',desc:'Combat use: a ward that soaks the next 14 damage taken (used when first hurt).',lore:'Flesh takes on the stubbornness of granite. Used once per personal combat when first hurt: a ward that soaks the next 14 damage you would take.',effect:{stat:'combatUse',use:'absorb',absorb:14,bonus:0},tier:2},
  {name:'Potion of Mirrors',desc:'Combat use: two mirror images that each soak one blow (used when below 70% health).',lore:'Quicksilver on the tongue and suddenly there are three of you. Used once per personal combat when below 70% health: two mirror images that each soak one blow.',effect:{stat:'combatUse',use:'mirror',images:2,below:0.7,bonus:0},tier:1},
  {name:'Smoke Bomb',desc:'Combat use: a cloud of smoke that adds +40% to any flight attempt (thrown when badly hurt).',lore:'Throw it down and vanish in the cloud. Used once per personal combat when badly hurt (below 35%): +40% to any attempt to flee.',effect:{stat:'combatUse',use:'flee',fleeBonus:40,below:0.35,bonus:0},tier:1},
  {name:'Potion of Fleetness',desc:'Combat use: +25% to flee and the foe -10% to hit you for the rest of the fight (drunk when badly hurt).',lore:'Hare\'s blood makes the legs quick and the body hard to pin. Drunk when badly hurt (below 40%): +25% to flee, and the foe suffers -10% to hit you for the rest of the fight.',effect:{stat:'combatUse',use:'flee',fleeBonus:25,toHitReduce:10,below:0.4,bonus:0},tier:1},
  {name:'Potion of Invisibility',desc:'Combat use: fade from sight — the foe suffers -25% to hit you for the rest of the fight (drunk when below half health).',lore:'One swallow and you fade from sight. Drunk when below half health: the foe suffers -25% to hit you for the rest of the fight.',effect:{stat:'combatUse',use:'invis',toHitReduce:25,below:0.5,bonus:0},tier:2},
  {name:'Scroll of Dispel',desc:'Combat use: strips every poison, burn and blinding from you (used when afflicted).',lore:'The clean words wash everything foul away. Used once per personal combat when afflicted: strips every poison, burn and blinding from you.',effect:{stat:'combatUse',use:'dispel',bonus:0},tier:1},
  {name:'Scroll of Life Drain',desc:'Combat use: 5-9 damage to the foe, and you recover the same (used when hurt).',lore:'The foe\'s vigour flows into you. Used once per personal combat when hurt: 5-9 damage to the foe, and you recover the same amount.',effect:{stat:'combatUse',use:'drain',dmg:[5,9],below:0.75,bonus:0},tier:2},
  {name:'Flask of Holy Water',desc:'Combat use: 12-18 damage against undead and fiends only (never used on the living).',lore:'Blessed water that scalds the unholy. Used once per personal combat, only against undead and fiends: 12-18 damage.',effect:{stat:'combatUse',use:'bane',dmg:[12,18],vs:['undead','fiend'],bonus:0},tier:1},
  {name:'Dragonbane Dart',desc:'Combat use: 10-16 damage against dragon-kind only.',lore:'A dart forged for one purpose. Used once per personal combat, only against dragon-kind: 10-16 damage.',effect:{stat:'combatUse',use:'bane',dmg:[10,16],vs:['dragon'],bonus:0},tier:1},
  {name:'Beastbane Snare',desc:'Combat use: a beast or vermin foe is snared and loses its next 2 actions.',lore:'An iron net a trapper would envy. Used once per personal combat, only against beasts and vermin: the foe is snared and loses its next 2 actions.',effect:{stat:'combatUse',use:'banestun',stun:2,vs:['beast','vermin'],bonus:0},tier:1},
  // ── RACE- AND ALIGNMENT-BOUND ITEMS: only a character of the named race or alignment can
  // equip or use these; in any other hand they are inert (and still worth giving to the right ally). ──
  {name:'Dwarf-Forged Warhammer',race:'Dwarven',desc:'[Dwarves only] Melee +3, and +3 damage on every melee hit.',lore:'Forged in the deep halls and quenched in meltwater, it falls with the weight of the mountain behind it. Dwarves only: Melee counts 3 levels higher and every melee hit deals 3 extra damage.',effect:{stat:'melee',bonus:3,pc:{dmgBonus:3}},slot:'weapon',tier:3},
  {name:'Deep-Delver\'s Lantern',desc:'[Dwarves only] Explorer +2.',lore:'A miner\'s lamp that shows every seam and side-tunnel. Dwarves only: Explorer skill counts as 2 levels higher; inert in any other hand.',race:'Dwarven',effect:{stat:'explorer',bonus:2},tier:1},
  {name:'Runic Ale-Horn',desc:'[Dwarves only] Max HP +6.',lore:'Ale drunk from it puts iron in the belly. Dwarves only: maximum HP +6; inert in any other hand.',race:'Dwarven',effect:{stat:'maxHp',bonus:6},tier:1},
  {name:'Ironclad Captain\'s Chain',desc:'[Dwarves only] Naval +2.',lore:'The chain of office of the Iron Fleet\'s first admiral. Dwarves only: Naval skill counts as 2 levels higher; inert in any other hand.',race:'Dwarven',effect:{stat:'naval',bonus:2},slot:'amulet',tier:1},
  {name:'Anvil-Brand Shield',desc:'[Dwarves only] Shield — combat use: a ward that soaks 12 damage, once per fight.',lore:'A shield stamped with the mark of the mountain forges. Dwarves only, used once per personal combat: a ward that soaks 12 damage; inert in any other hand.',race:'Dwarven',effect:{stat:'combatUse',use:'absorb',absorb:12,bonus:0},slot:'shield',tier:2},
  {name:'Moonsilver Bow',race:'Elven',desc:'[Elves only] Archery +3, +10% to hit and +2 damage on every hit.',lore:'Strung with a thread of moonlight that does not fray. Elves only: Archery counts 3 levels higher, you shoot at +10% to hit, and every hit deals 2 extra damage.',effect:{stat:'archery',bonus:3,pc:{hitBonus:10,dmgBonus:2}},slot:'weapon',tier:3},
  {name:'Starlight Diadem',desc:'[Elves only] Illusory Magic +2.',lore:'A circlet that scatters starlight into a hundred false shapes. Elves only: Illusory Magic skill counts as 2 levels higher; inert in any other hand.',race:'Elven',effect:{stat:'illusory',bonus:2},slot:'helm',tier:1},
  {name:'Cloak of Leaves',desc:'[Elves only] Spy +2.',lore:'Its wearer is just another shadow beneath the trees. Elves only: Spy skill counts as 2 levels higher; inert in any other hand.',race:'Elven',effect:{stat:'spy',bonus:2},slot:'cloak',tier:1},
  {name:'Wardancer\'s Anklets',desc:'[Elves only] March +2.',lore:'Bells of the swift dance that lighten every step. Elves only: March skill counts as 2 levels higher; inert in any other hand.',race:'Elven',effect:{stat:'march',bonus:2},slot:'armour',tier:1},
  {name:'Phial of Elvenmead',desc:'[Elves only] Combat use: recover 12 HP once per fight (used below half health).',lore:'The wine of the elven courts, sweet and restoring. Elves only, used once per personal combat when below half health: recover 12 HP; inert in any other hand.',race:'Elven',effect:{stat:'combatUse',use:'heal',amt:12,below:0.5,bonus:0},tier:2},
  {name:'Skull-Cleaver',race:'Orcish',desc:'[Orcs only] Melee +3, and +3 damage on every melee hit.',lore:'A notched, top-heavy thing that has never been sharpened and has never needed to be. Orcs only: Melee counts 3 levels higher and every melee hit deals 3 extra damage.',effect:{stat:'melee',bonus:3,pc:{dmgBonus:3}},slot:'weapon',tier:3},
  {name:'Warg-Hide Mantle',desc:'[Orcs only] Max HP +8.',lore:'The pelt of a black warg still keeps its savage vitality. Orcs only: maximum HP +8; inert in any other hand.',race:'Orcish',effect:{stat:'maxHp',bonus:8},slot:'cloak',tier:1},
  {name:'Blood-Drum of the Horde',desc:'[Orcs only] Tactical +2.',lore:'Its beat sets the whole horde moving as one. Orcs only: Tactical skill counts as 2 levels higher; inert in any other hand.',race:'Orcish',effect:{stat:'tactical',bonus:2},tier:1},
  {name:'Tusk Fetish',desc:'[Orcs only] Necromancy +2.',lore:'Tusks and finger-bones strung on a sinew cord; the dead answer to it. Orcs only: Necromancy skill counts as 2 levels higher; inert in any other hand.',race:'Orcish',effect:{stat:'necromancy',bonus:2},slot:'amulet',tier:1},
  {name:'Berserker\'s Draught',desc:'[Orcs only] Combat use: Melee +2 for the rest of the fight (drunk as the fight opens).',lore:'Red-eye brew: the world goes crimson and the pain goes away. Orcs only, drunk as a personal combat opens: Melee counts 2 higher for the rest of the fight; inert in any other hand.',race:'Orcish',effect:{stat:'combatUse',use:'buff',melee:2,bonus:0},tier:2},
  {name:'Banner of the Free Companies',desc:'[Humans only] All armies led: strength +2 each.',lore:'The standard the free companies fought under in the old wars. Humans only: every army you lead fights at +2 strength; inert in any other hand.',race:'Human',effect:{stat:'armyBonus',bonus:2},tier:2},
  {name:'Yeoman\'s Warbow',desc:'[Humans only] Archery +2.',lore:'A great yew bow of the border levies. Humans only: Archery skill counts as 2 levels higher; inert in any other hand.',race:'Human',effect:{stat:'archery',bonus:2},slot:'weapon',tier:1},
  {name:'Guildmaster\'s Seal',desc:'[Humans only] +5g collected each tax season (all item tax gold is capped at 5% of your realm\'s base tax income).',lore:'The seal of the counting-houses opens purses across the realm. Humans only: +5 gold collected each tax season; inert in any other hand.',race:'Human',effect:{stat:'taxBonus',bonus:5},slot:'ring',tier:1},
  {name:'Knight-Marshal\'s Baton',desc:'[Humans only] Tactical +2.',lore:'The baton of the crown\'s constable. Humans only: Tactical skill counts as 2 levels higher; inert in any other hand.',race:'Human',effect:{stat:'tactical',bonus:2},tier:1},
  {name:'Chirurgeon\'s Kit',desc:'[Humans only] Combat use: recover 10 HP once per fight (used below half health).',lore:'Needles, gut and a steady hand. Humans only, used once per personal combat when below half health: recover 10 HP; inert in any other hand.',race:'Human',effect:{stat:'combatUse',use:'heal',amt:10,below:0.5,bonus:0},tier:1},
  {name:'Paladin\'s Sword',alignment:'Good',desc:'[Good characters only] Melee +3, +10% to hit and +2 damage on every melee hit.',lore:'Plain, well kept, and carried by better people than most. Good characters only: Melee counts 3 levels higher, you strike at +10% to hit, and every melee hit deals 2 extra damage.',effect:{stat:'melee',bonus:3,pc:{hitBonus:10,dmgBonus:2}},slot:'weapon',tier:3},
  {name:'Shield of the Innocent',desc:'[Good characters only] All armies led: +1 quality tier when defending a home province.',lore:'The folk fight the harder knowing who they shield. Good characters only: every army you lead fights one quality tier higher when defending a home province; inert in any other hand.',alignment:'Good',effect:{stat:'homeDefBonus',bonus:1},slot:'shield',tier:2},
  {name:'Oathkeeper\'s Ring',desc:'[Good characters only] Max HP +6.',lore:'The wearer\'s word holds, and so does the wearer. Good characters only: maximum HP +6; inert in any other hand.',alignment:'Good',effect:{stat:'maxHp',bonus:6},slot:'ring',tier:1},
  {name:'Tyrant\'s Sceptre',desc:'[Evil characters only] +5g collected each tax season (all item tax gold is capped at 5% of your realm\'s base tax income).',lore:'A rod of iron rule; the taxes come in on time. Evil characters only: +5 gold collected each tax season; inert in any other hand.',alignment:'Evil',effect:{stat:'taxBonus',bonus:5},slot:'weapon',tier:1},
  {name:'Poisoner\'s Ring',desc:'[Evil characters only] Thief +2.',lore:'A hollow signet with a hinged lid. Evil characters only: Thief skill counts as 2 levels higher; inert in any other hand.',alignment:'Evil',effect:{stat:'thief',bonus:2},slot:'ring',tier:1},
  {name:'Mask of the Torturer',desc:'[Evil characters only] Combat use: the foe is terrified — -25% to hit (fades 5% per round).',lore:'One look and the foe\'s courage fails. Evil characters only, used once per personal combat: the foe suffers -25% to hit, fading 5% per round; inert in any other hand.',alignment:'Evil',effect:{stat:'combatUse',use:'pen',hitPen:25,bonus:0},slot:'helm',tier:1},
  {name:'Merchant-Prince\'s Ledger',desc:'[Neutral characters only] +1g collected per province owned (all item tax gold is capped at 5% of your realm\'s base tax income).',lore:'Every province is a line in it, and every line pays. Neutral characters only: +1 gold collected per province owned; inert in any other hand.',alignment:'Neutral',effect:{stat:'taxPerProv',bonus:1},tier:2},
  {name:'Broker\'s Signet',desc:'[Neutral characters only] Sage +2.',lore:'The ring of the fair deal, and of the one who knows the price of everything. Neutral characters only: Sage skill counts as 2 levels higher; inert in any other hand.',alignment:'Neutral',effect:{stat:'sage',bonus:2},slot:'ring',tier:1},
  {name:'Caravan Master\'s Boots',desc:'[Neutral characters only] March +2.',lore:'Boots that have walked every trade road in the world. Neutral characters only: March skill counts as 2 levels higher; inert in any other hand.',alignment:'Neutral',effect:{stat:'march',bonus:2},slot:'armour',tier:1},
  {name:'Halo of the Martyr',desc:'[Divine characters only] White Magic +2.',lore:'A faint light that never quite leaves the wearer\'s brow. Divine characters only: White Magic skill counts as 2 levels higher; inert in any other hand.',alignment:'Divine',effect:{stat:'white',bonus:2},slot:'helm',tier:1},
  {name:'Censer of Consecration',desc:'[Divine characters only] Combat use: holy fire for 10-16 damage, doubled against undead and fiends.',lore:'Holy fire swings from its chains. Divine characters only, used once per personal combat: 10-16 damage, doubled against undead and fiends; inert in any other hand.',alignment:'Divine',effect:{stat:'combatUse',use:'dmg',dmg:[10,16],doubleVs:['undead','fiend'],bonus:0},tier:2},
  {name:'Relic of the Saint',desc:'[Divine characters only] Max HP +6.',lore:'A fingerbone of the blessed, and the blessing lingers. Divine characters only: maximum HP +6; inert in any other hand.',alignment:'Divine',effect:{stat:'maxHp',bonus:6},slot:'amulet',tier:1},
  {name:'Antler Crown',desc:'[Druidic characters only] Druid +2.',lore:'The crown of the stag-lord; the wild bows to its wearer. Druidic characters only: Druid skill counts as 2 levels higher; inert in any other hand.',alignment:'Druidic',effect:{stat:'druid',bonus:2},slot:'helm',tier:1},
  {name:'Seed of the World-Tree',desc:'[Druidic characters only] Combat use: heal 4 HP at the start of each of the next 4 rounds (used when below 70% health).',lore:'Plant it in a wound and life grows back. Druidic characters only, used once per personal combat when below 70% health: heal 4 HP at the start of each of the next 4 rounds; inert in any other hand.',alignment:'Druidic',effect:{stat:'combatUse',use:'hot',amt:4,rounds:4,below:0.7,bonus:0},tier:1},
  {name:'Bark-Skin Girdle',desc:'[Druidic characters only] Max HP +6.',lore:'A belt of living wood that toughens the body it girds. Druidic characters only: maximum HP +6; inert in any other hand.',alignment:'Druidic',effect:{stat:'maxHp',bonus:6},slot:'armour',tier:1},
  {name:'Totem of the Old Gods',desc:'[Pagan characters only] Explorer +2.',lore:'Carry it and the ancestors show you the hidden ways. Pagan characters only: Explorer skill counts as 2 levels higher; inert in any other hand.',alignment:'Pagan',effect:{stat:'explorer',bonus:2},tier:1},
  {name:'Wolf-Pelt Cloak',desc:'[Pagan characters only] Max HP +6.',lore:'The mantle of the Wild Hunt; the pack\'s strength runs in it. Pagan characters only: maximum HP +6; inert in any other hand.',alignment:'Pagan',effect:{stat:'maxHp',bonus:6},slot:'cloak',tier:1},
  {name:'Blood-Rune Knife',desc:'[Pagan characters only] Combat use: 6-10 damage to the foe, and you recover the same (used when hurt).',lore:'A sacrificial blade that feeds the old gods and the hand that wields it. Pagan characters only, used once per personal combat when hurt: 6-10 damage to the foe, and you recover the same; inert in any other hand.',alignment:'Pagan',effect:{stat:'combatUse',use:'drain',dmg:[6,10],below:0.75,bonus:0},tier:2},
  {name:'Lich\'s Phylactery Shard',desc:'[Undead characters only] Necromancy +2.',lore:'A splinter of a soul-jar, still cold with what it held. Undead characters only: Necromancy skill counts as 2 levels higher; inert in any other hand.',alignment:'Undead',effect:{stat:'necromancy',bonus:2},slot:'amulet',tier:1},
  {name:'Crown of the Barrow-King',desc:'[Undead characters only] Skeletal Legions you lead: +4 strength.',lore:'The bone lord\'s diadem; the dead march the harder beneath it. Undead characters only: Skeletal Legions you lead fight at +4 strength; inert in any other hand.',alignment:'Undead',effect:{stat:'undeadBonus',bonus:1},slot:'helm',tier:1},
  {name:'Grave-Cold Blade',alignment:'Undead',desc:'[Undead characters only] Melee +3, +1 damage on every melee hit, and you drink a quarter of the harm you deal.',lore:'It is never warm, and neither is the hand that holds it. Undead characters only: Melee counts 3 levels higher, every melee hit deals 1 extra damage, and a quarter of the damage you deal returns to you as health.',effect:{stat:'melee',bonus:3,pc:{dmgBonus:1,drain:0.25}},slot:'weapon',tier:3},
  // ── Economy ──
  {name:'Ring of Wealth',desc:'+5g collected each tax season (item tax gold is capped at 5% of your realm\'s base tax income)',lore:'Gold seems to find its way to whoever wears it. +5 gold collected each tax season.',effect:{stat:'taxBonus',bonus:5},tier:1},
  {name:'Merchant\'s Ledger',desc:'+1g collected per province owned (item tax gold is capped at 5% of your realm\'s base tax income)',lore:'A trader\'s tally-book that finds a coin or two in every province. +1 gold collected per province owned.',effect:{stat:'taxPerProv',bonus:1},tier:1},
  // ── Special ──
  {name:'Philosopher\'s Stone',desc:'Once per game: instantly promote all armies one quality tier',lore:'The alchemists\' great prize: it turns raw levies into seasoned soldiers as surely as lead into gold. A LEGENDARY relic, usable once per game: instantly promote all your armies one quality tier.',effect:{stat:'massPromote',bonus:1},tier:3},
  {name:'Cloak of Many Faces',desc:'This hero may not be targeted by Spy, Psychic Blast, Curse or Encounter Character orders',lore:'Its wearer has no face anyone can remember. A LEGENDARY relic: this character cannot be targeted by Spy, Psychic Blast, Curse or Encounter Character orders.',effect:{stat:'hidden',bonus:1},tier:3},
  {name:'Crown of Command',desc:'All characters in the same province gain +1 to all skills for the duration of the turn',lore:'The crown of the old Empire\'s war-kings; those who stand near it find their skills sharpened. A LEGENDARY relic: every character in the same province, friend or foe, counts all skills 1 level higher for the turn.',effect:{stat:'aura',bonus:1},tier:3},
  // ── Three added legendaries (2026-07 — brings the Legendary tier to 10 "named relics", one per
  // Legacy point in the Titles/Reckoning scoring. Each reuses an already-wired effect stat so
  // none is a dead item: melee (effStat), taxBonus (tax collection), armyBonus (armStr). ──
  {name:'Sword of the First Emperor',desc:'The blade that founded the old Empire. Melee +4.',lore:'The blade that founded the old Empire, and the greatest weapon in the world. A LEGENDARY relic: Melee skill counts as 4 levels higher.',effect:{stat:'melee',bonus:4},tier:3},
  {name:'Imperial Regalia',desc:'The crown, orb and sceptre of the vanished throne. +10g collected each tax season (item tax gold is capped at 5% of your realm\'s base tax income).',lore:'The crown, orb and sceptre of the vanished throne; whoever holds them commands a tithe from every corner of the land. A LEGENDARY relic: +10 gold collected each tax season.',effect:{stat:'taxBonus',bonus:10},tier:3},
  {name:'Standard of the Nine Legions',desc:'The war-banner under which the Empire was won. All armies you lead: strength +5 each.',lore:'The war-banner under which the Empire was won. A LEGENDARY relic: every army you lead fights at +5 strength.',effect:{stat:'armyBonus',bonus:5},tier:3},
  // ── ARMOUR ── fifteen worn defences, each mitigating damage in a different way. Fourteen sit in
  // the single `armour` slot (one worn at a time; cloaks/helms are separate slots); the Tower
  // Shield is `shield`, as are the six further shields below Warden's Scale. Effects resolve in
  // personal combat only — see pcArmourOf / pcTakeHit / pcRoundStart / pcHitChance. `stat:'armour'`
  // + one `ward` key.
  {name:'Dwarf-Forged Hauberk',desc:'Armour: every melee blow that lands on you deals 2 less damage (never below 1).',lore:'Rings of mountain steel, each one closed by a smith who never hurried. Every melee blow that lands on the wearer deals 2 less damage, never below 1.',effect:{stat:'armour',ward:'meleeDR',amt:2,bonus:0},slot:'armour',tier:1},
  {name:'Arrow-Turning Brigandine',desc:'Armour: every arrow or missile that strikes you deals 3 less damage (never below 1).',lore:'Overlapping plates riveted beneath stout cloth, angled so shafts skate away. Every arrow or missile that strikes the wearer deals 3 less damage, never below 1.',effect:{stat:'armour',ward:'arrowDR',amt:3,bonus:0},slot:'armour',tier:1},
  {name:'Troll-Hide Jerkin',desc:'Armour: recover 2 HP at the start of every combat round.',lore:'Cured troll-skin that has not quite stopped living. The wearer recovers 2 HP at the start of every round of personal combat.',effect:{stat:'armour',ward:'regen',amt:2,bonus:0},slot:'armour',tier:1},
  {name:'Thornwood Cuirass',desc:'Armour: whoever lands a melee blow on you takes 2 damage back.',lore:'Breastplate of living blackthorn; it bites back. Whoever lands a melee blow on the wearer takes 2 damage in return.',effect:{stat:'armour',ward:'thorns',amt:2,bonus:0},slot:'armour',tier:1},
  {name:'Tower Shield of the Wall',desc:'Shield: 20% chance to block any melee blow or arrow outright.',lore:'A door-sized slab of oak and iron carried by the shield-wall\'s best. One melee blow or arrow in five is blocked outright.',effect:{stat:'armour',ward:'block',pct:20,bonus:0},slot:'shield',tier:1},
  {name:'Serpent-Scale Coat',desc:'Armour: beasts, vermin and dragons deal 3 less damage to you with every hit (never below 1).',lore:'Scales of some great serpent, still faintly warm. Beasts, vermin and dragon-kind deal 3 less damage to the wearer with every hit, never below 1.',effect:{stat:'armour',ward:'natureDR',amt:3,bonus:0},slot:'armour',tier:1},
  {name:'Grave-Iron Plate',desc:'Armour: undead and fiends deal 3 less damage to you with every hit (never below 1).',lore:'Plate quenched in consecrated ash; the dead and the damned find it hard to bite. Undead and fiends deal 3 less damage to the wearer with every hit, never below 1.',effect:{stat:'armour',ward:'darkDR',amt:3,bonus:0},slot:'armour',tier:1},
  {name:'Blood-Bound Cuirass',desc:'Armour: the first blow, arrow or spell that lands on you each fight does no damage at all.',lore:'Old blood in the steel takes the first wound for its wearer. The first blow, arrow or spell that lands on the wearer in each fight does no damage at all.',effect:{stat:'armour',ward:'firstHit',bonus:0},slot:'armour',tier:1},
  {name:'Spellwarded Robe',desc:'Armour: spells and monster powers deal 30% less damage to you.',lore:'Silk stitched through with silver sigils that drink hostile magic. Spells and guardian powers deal 30% less damage to the wearer.',effect:{stat:'armour',ward:'spellPct',pct:30,bonus:0},slot:'armour',tier:2},
  {name:'Quicksilver Mail',desc:'Armour: enemies have −10% to hit you in personal combat.',lore:'Mail so light it seems to move before the wearer does. Every foe has 10% less chance to hit the wearer in personal combat.',effect:{stat:'armour',ward:'dodge',pct:10,bonus:0},slot:'armour',tier:2},
  {name:'Ashen Plate',desc:'Armour: burns, poisons and bleeding never take hold on you.',lore:'Plate forged in a dead volcano; nothing lingers on it. Burns, poisons, bleeding and every other lingering harm never take hold on the wearer.',effect:{stat:'armour',ward:'dotImmune',bonus:0},slot:'armour',tier:2},
  {name:'Bulwark Breastplate',desc:'Armour: no single hit may cost you more than 25% of your maximum HP.',lore:'A slab of layered steel that spreads the heaviest blow across the whole body. No single hit may cost the wearer more than a quarter of their maximum HP.',effect:{stat:'armour',ward:'cap',pct:25,bonus:0},slot:'armour',tier:2},
  {name:'Last-Stand Plate',desc:'Armour: once per fight, the first time you fall below 30% HP you recover 25% of your maximum HP.',lore:'Worn by a champion who would not go down; some of that stubbornness stayed. Once per fight, the first time the wearer falls below 30% HP they recover a quarter of their maximum HP on the spot.',effect:{stat:'armour',ward:'secondWind',pct:25,bonus:0},slot:'armour',tier:2},
  {name:'Steadfast Harness',desc:'Armour: to-hit penalties laid on you fade twice as fast, and half of all stuns and lost actions are shrugged off.',lore:'Harness blessed against faltering. Penalties to the wearer\'s aim fade twice as fast, and half of all stuns and lost actions are shrugged off.',effect:{stat:'armour',ward:'resist',bonus:0},slot:'armour',tier:2},
  // ── SHIELDS — `shield` slot, six more ways to blunt harm ──
  {name:'Kite Shield of the Marches',desc:'Shield: 30% chance to block any arrow or missile outright.',lore:'Long and narrow, made for riders who take fire on the road. Three arrows in ten glance off it entirely.',effect:{stat:'armour',ward:'arrowBlock',pct:30,bonus:0},slot:'shield',tier:1},
  {name:'Bronze Buckler',desc:'Shield: melee blows deal 1 less damage and foes have −5% to hit you.',lore:'Small, quick and always in the way. Melee blows on the bearer deal 1 less damage, and every foe has 5% less chance to hit them.',effect:{stat:'armour',ward:'buckler',bonus:0},slot:'shield',tier:1},
  {name:'Oaken Roundshield',desc:'Shield: the first two hits to land on you each fight deal half damage.',lore:'Heavy oak rimmed in iron, raised high while the bearer reads the foe. The first two hits to land on the bearer in each fight deal half damage.',effect:{stat:'armour',ward:'openGuard',hits:2,pct:50,bonus:0},slot:'shield',tier:1},
  {name:'Mirror-Bright Shield',desc:'Shield: 25% chance any hostile spell or guardian power is turned away harmlessly.',lore:'Polished until it holds the sky. One hostile spell or guardian power in four is turned away with no effect at all.',effect:{stat:'armour',ward:'spellBlock',pct:25,bonus:0},slot:'shield',tier:2},
  {name:'Shield of the Ward-Saints',desc:'Shield: at the start of every round a ward forms that soaks the next 4 damage.',lore:'Painted with saints who take the blow for the bearer. At the start of every round a fresh ward forms that soaks the next 4 damage.',effect:{stat:'armour',ward:'roundWard',amt:4,bonus:0},slot:'shield',tier:2},
  {name:'Dragonbone Shield',desc:'Shield: you can never be stunned, entranced, paralysed or knocked back.',lore:'Cut from the breastbone of a wyrm; nothing shakes it or the arm behind it. The bearer can never be stunned, entranced, paralysed or knocked back.',effect:{stat:'armour',ward:'stunImmune',bonus:0},slot:'shield',tier:2},
  {name:'Warden\'s Scale',desc:'Armour: while below half HP, every hit on you deals 25% less damage.',lore:'Scale-mail of the border wardens, made for the long last hour. While the wearer is below half HP, every hit on them deals 25% less damage.',effect:{stat:'armour',ward:'lowHp',pct:25,bonus:0},slot:'armour',tier:2},
  // ── 2026-09-11: 74 new slot items ANYONE can use — 16 weapons, 16 helms, 16 cloaks, 16 rings, 10
  // amulets. `effect.pc` is a personal-combat rider read by pcApplyFx (ward / aura / burn / drain /
  // hitBonus / dmgBonus), usable alongside a skill bonus. Inline `slot` keeps the slot tables
  // untouched. No alternate names. ── Weapons ──
  {name:'Woodsman\'s Axe',slot:'weapon',desc:'Melee +1',lore:'A plain felling axe with a wicked edge. Melee skill counts 1 level higher in personal combat.',effect:{stat:'melee',bonus:1},tier:1},
  {name:'Hunter\'s Recurve',slot:'weapon',desc:'Archery +1',lore:'A short horn-backed bow made for the chase. Archery skill counts 1 level higher.',effect:{stat:'archery',bonus:1},tier:1},
  {name:'Serpent-Fang Dagger',slot:'weapon',desc:'Weapon: +10% to hit in personal combat.',lore:'A curved blade that seems to find the gap before you do. +10% to hit with every attack in personal combat.',effect:{stat:'pc',pc:{hitBonus:10}},tier:1},
  {name:'Warden\'s Spear',slot:'weapon',desc:'Melee +1, and melee blows against you deal 1 less damage.',lore:'A long ash spear that keeps the foe at arm\'s length. Melee counts 1 higher; every melee blow that lands on you deals 1 less.',effect:{stat:'melee',bonus:1,pc:{ward:'meleeDR',amt:1}},tier:1},
  {name:'Sling of Whispering Stones',slot:'weapon',desc:'Archery +1, +5% to hit.',lore:'The stones seem to whisper as they fly. Archery counts 1 higher and every attack is +5% to hit.',effect:{stat:'archery',bonus:1,pc:{hitBonus:5}},tier:1},
  {name:'Rod of the Pale Court',slot:'weapon',desc:'Necromancy +1, and undead and fiends deal 2 less damage to you.',lore:'A bone-white rod that the dead recognise as one of their own. Necromancy counts 1 higher; undead and fiends deal 2 less with every hit.',effect:{stat:'necromancy',bonus:1,pc:{ward:'darkDR',amt:2}},tier:1},
  {name:'Crozier of Dawn',slot:'weapon',desc:'White Magic +1, recover 1 HP each combat round.',lore:'A shepherd\'s crook chased with gold. White Magic counts 1 higher and you recover 1 HP at the start of every round.',effect:{stat:'white',bonus:1,pc:{ward:'regen',amt:1}},tier:1},
  {name:'Wand of the Fox',slot:'weapon',desc:'Illusory Magic +1, foes −5% to hit you.',lore:'A slender wand that makes you a little harder to look at straight. Illusory counts 1 higher and enemies have −5% to hit you.',effect:{stat:'illusory',bonus:1,pc:{ward:'dodge',pct:5}},tier:1},
  {name:'Greatsword of the Marches',slot:'weapon',desc:'Weapon: +3 damage on every successful melee attack.',lore:'A two-handed blade from the border wars. Every melee hit you land deals 3 extra damage.',effect:{stat:'pc',pc:{dmgBonus:3}},tier:2},
  {name:'Composite Bow of the Steppe',slot:'weapon',desc:'Archery +2',lore:'Horn, sinew and wood laminated by horse-lords. Archery counts 2 levels higher.',effect:{stat:'archery',bonus:2},tier:2},
  {name:'Leech-Blade',slot:'weapon',desc:'Weapon: you recover half the damage you deal with melee hits.',lore:'A black sword that drinks. Half of every melee wound you deal returns to you as health.',effect:{stat:'pc',pc:{drain:0.5}},tier:2},
  {name:'Brand of the Salamander',slot:'weapon',desc:'Weapon: a foe in melee reach takes 2 fire damage every round.',lore:'A blade that never cools. Any foe at melee range takes 2 damage at the end of each round.',effect:{stat:'pc',pc:{burn:2}},tier:2},
  {name:'Executioner\'s Maul',slot:'weapon',desc:'Weapon: +4 damage on every successful melee attack.',lore:'Ugly, heavy and final. Every melee hit you land deals 4 extra damage.',effect:{stat:'pc',pc:{dmgBonus:4}},tier:2},
  // renamed from "Duellist's Rapier". There were TWO different items under that one name — this
  // tier-2 defensive blade and the tier-3 Melee +3 / +8%-to-hit rapier at ~3307 — and every item
  // lookup in the engine is keyed by NAME (ITEM_SLOT_OF, _ITEM_ALT_BASE, ITEM_LORE_BY_NAME, the
  // _awardedItems reservation and the lair-uniqueness check). A saved item called "Duellist's
  // Rapier" therefore resolved to whichever of the two the scan reached first. Distinct name,
  // distinct item.
  {name:'Fencer\'s Rapier',slot:'weapon',desc:'Melee +1, foes −10% to hit you.',lore:'Light, quick and made for the salle. Melee counts 1 higher and your guard gives enemies −10% to hit you.',effect:{stat:'melee',bonus:1,pc:{ward:'dodge',pct:10}},tier:2},
  {name:'Staff of Ashes',slot:'weapon',desc:'Elemental Magic +2',lore:'Charred oak that still smoulders at the tip. Elemental Magic counts 2 levels higher.',effect:{stat:'elemental',bonus:2},tier:2},
  {name:'Flail of Thunder',slot:'weapon',desc:'Melee +1, +2 damage per melee hit.',lore:'Each strike lands like a thunderclap. Melee counts 1 higher and every melee hit deals 2 extra damage.',effect:{stat:'melee',bonus:1,pc:{dmgBonus:2}},tier:2},
  // ── Helms ──
  {name:'Iron Sallet',slot:'helm',desc:'Helm: melee blows deal 1 less damage to you.',lore:'A plain soldier\'s helm. Every melee blow that lands on you deals 1 less (never below 1).',effect:{stat:'pc',pc:{ward:'meleeDR',amt:1}},tier:1},
  {name:'Visored Bascinet',slot:'helm',desc:'Helm: arrows and missiles deal 2 less damage to you.',lore:'The visor turns shafts that would have taken an eye. Every arrow or missile that strikes you deals 2 less.',effect:{stat:'pc',pc:{ward:'arrowDR',amt:2}},tier:1},
  {name:'Circlet of Clear Thought',slot:'helm',desc:'Psychic Magic +1',lore:'A thin silver band that quiets the noise of other minds. Psychic Magic counts 1 level higher.',effect:{stat:'psychic',bonus:1},tier:1},
  {name:'Helm of the Stalwart',slot:'helm',desc:'Max HP +5',lore:'Heavy, dented and utterly reliable. Maximum HP +5.',effect:{stat:'maxHp',bonus:5},tier:1},
  {name:'Crown of the Tactician',slot:'helm',desc:'Tactical +1',lore:'A circlet worked with the shapes of the classic formations. Tactical counts 1 level higher.',effect:{stat:'tactical',bonus:1},tier:1},
  {name:'Cap of the Pathfinder',slot:'helm',desc:'Explorer +1',lore:'A weathered cap whose wearer always seems to know the next ridge. Explorer counts 1 level higher.',effect:{stat:'explorer',bonus:1},tier:1},
  {name:'Hood of the Listener',slot:'helm',desc:'Spy +1',lore:'A deep hood that hears what it should not. Spy counts 1 level higher.',effect:{stat:'spy',bonus:1},tier:1},
  {name:'Scholar\'s Cap',slot:'helm',desc:'Sage +1',lore:'The square cap of the old academies. Sage counts 1 level higher.',effect:{stat:'sage',bonus:1},tier:1},
  {name:'Warlord\'s Crest',slot:'helm',desc:'Melee +1',lore:'A helm crested with a snarling beast that makes its wearer bolder. Melee counts 1 level higher.',effect:{stat:'melee',bonus:1},tier:1},
  {name:'Archer\'s Cap',slot:'helm',desc:'Archery +1',lore:'A light leather cap that keeps the sun from the eyes. Archery counts 1 level higher.',effect:{stat:'archery',bonus:1},tier:1},
  {name:'Coronet of the Tithe',slot:'helm',desc:'+3g collected each tax season (item tax gold is capped at 5% of your realm\'s base tax income)',lore:'Wear it and the stewards find a little more in every chest. +3 gold each tax season.',effect:{stat:'taxBonus',bonus:3},tier:1},
  {name:'Helm of the Unflinching',slot:'helm',desc:'Helm: foes have −5% to hit you.',lore:'Its steady gaze unsettles those who face it. Enemies have −5% to hit you in personal combat.',effect:{stat:'pc',pc:{aura:5}},tier:1},
  {name:'Helm of Iron Will',slot:'helm',desc:'Helm: you can never be stunned, entranced, paralysed or knocked back.',lore:'A helm forged for a mind that will not be moved. No stun, entrancement, paralysis or knockback ever takes hold.',effect:{stat:'pc',pc:{ward:'stunImmune'}},tier:2},
  {name:'Great Helm of the Bulwark',slot:'helm',desc:'Helm: no single hit may cost you more than 30% of your maximum HP.',lore:'A great helm that spreads the worst blow across the whole body. No single hit costs more than 30% of your maximum HP.',effect:{stat:'pc',pc:{ward:'cap',pct:30}},tier:2},
  {name:'Dragon-Crest Helm',slot:'helm',desc:'Helm: beasts, vermin and dragons deal 3 less damage to you.',lore:'Crested with a dragon\'s own scale, it turns fang and claw aside. Beasts, vermin and dragons deal 3 less with every hit.',effect:{stat:'pc',pc:{ward:'natureDR',amt:3}},tier:2},
  {name:'Diadem of the Second Sight',slot:'helm',desc:'Illusory Magic +2',lore:'A diadem set with a stone that shows what is not there. Illusory Magic counts 2 levels higher.',effect:{stat:'illusory',bonus:2},tier:2},
  // ── Cloaks ──
  {name:'Cloak of the Wayfarer',slot:'cloak',desc:'March +1',lore:'A travel-stained cloak that makes the miles shorter. March counts 1 level higher.',effect:{stat:'march',bonus:1},tier:1},
  {name:'Mantle of the Deep',slot:'cloak',desc:'Naval +1',lore:'Sealskin and salt. Naval counts 1 level higher.',effect:{stat:'naval',bonus:1},tier:1},
  {name:'Cloak of Embers',slot:'cloak',desc:'Cloak: a foe in melee reach takes 1 fire damage every round.',lore:'It smoulders without burning its wearer. Any foe at melee range takes 1 damage at the end of each round.',effect:{stat:'pc',pc:{burn:1}},tier:1},
  {name:'Cloak of the Grove',slot:'cloak',desc:'Druid +1',lore:'Woven of living leaves that never wither. Druid counts 1 level higher.',effect:{stat:'druid',bonus:1},tier:1},
  {name:'Weatherworn Cape',slot:'cloak',desc:'Cloak: burns, poisons and bleeding never take hold on you.',lore:'A cape that has shed a hundred storms. No burn, poison or bleed ever takes hold on you.',effect:{stat:'pc',pc:{ward:'dotImmune'}},tier:1},
  {name:'Mantle of Thorns',slot:'cloak',desc:'Cloak: whoever lands a melee blow on you takes 1 damage back.',lore:'Bramble worked into the weave. Anyone who lands a melee blow on you takes 1 damage.',effect:{stat:'pc',pc:{ward:'thorns',amt:1}},tier:1},
  {name:'Cutpurse\'s Cloak',slot:'cloak',desc:'Thief +1',lore:'Sewn with more pockets than seams. Thief counts 1 level higher.',effect:{stat:'thief',bonus:1},tier:1},
  {name:'Cape of the Stormrider',slot:'cloak',desc:'Elemental Magic +1',lore:'It crackles when the weather turns. Elemental Magic counts 1 level higher.',effect:{stat:'elemental',bonus:1},tier:1},
  {name:'Shroud of the Barrow',slot:'cloak',desc:'Necromancy +1',lore:'Grave-linen that never quite warms. Necromancy counts 1 level higher.',effect:{stat:'necromancy',bonus:1},tier:1},
  {name:'Mantle of the Confessor',slot:'cloak',desc:'White Magic +1',lore:'Plain white wool, and the peace that comes with it. White Magic counts 1 level higher.',effect:{stat:'white',bonus:1},tier:1},
  {name:'Cloak of Still Water',slot:'cloak',desc:'Psychic Magic +1',lore:'Its wearer\'s thoughts settle like a pond at dusk. Psychic Magic counts 1 level higher.',effect:{stat:'psychic',bonus:1},tier:1},
  {name:'Shroud of Moths',slot:'cloak',desc:'Cloak: foes have −10% to hit you.',lore:'A cloak that flutters at the edge of sight. Enemies have −10% to hit you in personal combat.',effect:{stat:'pc',pc:{ward:'dodge',pct:10}},tier:2},
  {name:'Warden\'s Greatcloak',slot:'cloak',desc:'Cloak: 20% chance to block any arrow or missile outright.',lore:'Thick enough to catch a shaft in its folds. 20% chance any arrow or missile is stopped outright.',effect:{stat:'pc',pc:{ward:'arrowBlock',pct:20}},tier:2},
  {name:'Cloak of the Hearth',slot:'cloak',desc:'Cloak: recover 2 HP at the start of every combat round.',lore:'Warm as a fireside however cold the field. Recover 2 HP at the start of every round.',effect:{stat:'pc',pc:{ward:'regen',amt:2}},tier:2},
  {name:'Cloak of Stillness',slot:'cloak',desc:'Cloak: spells and monster powers deal 25% less damage to you.',lore:'Magic slides off it like rain off slate. Spells and guardian powers deal 25% less damage to you.',effect:{stat:'pc',pc:{ward:'spellPct',pct:25}},tier:2},
  {name:'Marshal\'s Mantle',slot:'cloak',desc:'All armies you lead: strength +2 each.',lore:'The scarlet mantle soldiers look for in the line. Every army you lead fights at +2 strength.',effect:{stat:'armyBonus',bonus:2},tier:2},
  // ── Rings ──
  {name:'Ring of Vigour',slot:'ring',desc:'Max HP +4',lore:'A heavy band that keeps the heart beating steadily. Maximum HP +4.',effect:{stat:'maxHp',bonus:4},tier:1},
  {name:'Ring of the Duellist',slot:'ring',desc:'Melee +1',lore:'Worn on the sword hand. Melee counts 1 level higher.',effect:{stat:'melee',bonus:1},tier:1},
  {name:'Ring of the Bowyer',slot:'ring',desc:'Archery +1',lore:'A thumb-ring of horn. Archery counts 1 level higher.',effect:{stat:'archery',bonus:1},tier:1},
  {name:'Ring of the Tide',slot:'ring',desc:'Naval +1',lore:'Green sea-glass in a silver band. Naval counts 1 level higher.',effect:{stat:'naval',bonus:1},tier:1},
  {name:'Ring of the Long Road',slot:'ring',desc:'March +1',lore:'A worn band that lightens the pack. March counts 1 level higher.',effect:{stat:'march',bonus:1},tier:1},
  {name:'Ring of Ember',slot:'ring',desc:'Elemental Magic +1',lore:'Warm to the touch, always. Elemental Magic counts 1 level higher.',effect:{stat:'elemental',bonus:1},tier:1},
  {name:'Ring of Bone',slot:'ring',desc:'Necromancy +1',lore:'Carved from a knuckle that was not given willingly. Necromancy counts 1 level higher.',effect:{stat:'necromancy',bonus:1},tier:1},
  {name:'Ring of the Dawn',slot:'ring',desc:'White Magic +1',lore:'A pale gold band that catches the first light. White Magic counts 1 level higher.',effect:{stat:'white',bonus:1},tier:1},
  {name:'Ring of Glamour',slot:'ring',desc:'Illusory Magic +1',lore:'It is never quite the colour you remember. Illusory Magic counts 1 level higher.',effect:{stat:'illusory',bonus:1},tier:1},
  {name:'Ring of the Inner Eye',slot:'ring',desc:'Psychic Magic +1',lore:'A dark stone that seems to look back. Psychic Magic counts 1 level higher.',effect:{stat:'psychic',bonus:1},tier:1},
  {name:'Ring of the Green',slot:'ring',desc:'Druid +1',lore:'A twist of living vine. Druid counts 1 level higher.',effect:{stat:'druid',bonus:1},tier:1},
  {name:'Ring of the Cartographer',slot:'ring',desc:'Explorer +1',lore:'A compass-rose signet. Explorer counts 1 level higher.',effect:{stat:'explorer',bonus:1},tier:1},
  {name:'Ring of the Shadow',slot:'ring',desc:'Spy +1',lore:'Black iron that draws no eye. Spy counts 1 level higher.',effect:{stat:'spy',bonus:1},tier:1},
  {name:'Signet of the Marshal',slot:'ring',desc:'Tactical +1',lore:'The seal of a forgotten marshal. Tactical counts 1 level higher.',effect:{stat:'tactical',bonus:1},tier:1},
  {name:'Ring of Steady Hands',slot:'ring',desc:'Ring: +5% to hit in personal combat.',lore:'The tremor leaves the hand that wears it. +5% to hit with every attack in personal combat.',effect:{stat:'pc',pc:{hitBonus:5}},tier:1},
  {name:'Ring of the Warding Circle',slot:'ring',desc:'Ring: 15% chance any hostile spell or guardian power is turned away harmlessly.',lore:'A ring inscribed with a circle that closes when magic comes near. 15% chance any hostile spell or guardian power is turned aside.',effect:{stat:'pc',pc:{ward:'spellBlock',pct:15}},tier:2},
  // ── Amulets ──
  {name:'Amulet of the Oak',slot:'amulet',desc:'Max HP +6',lore:'An acorn of dark gold on a leather cord. Maximum HP +6.',effect:{stat:'maxHp',bonus:6},tier:2},
  {name:'Talisman of the Bear',slot:'amulet',desc:'Amulet: +2 damage on every successful melee attack.',lore:'A bear\'s claw that lends its strength to the arm. Every melee hit you land deals 2 extra damage.',effect:{stat:'pc',pc:{dmgBonus:2}},tier:1},
  {name:'Pendant of the Tides',slot:'amulet',desc:'Naval +2',lore:'A pearl that rises and falls with the moon. Naval counts 2 levels higher.',effect:{stat:'naval',bonus:2},tier:2},
  {name:'Amulet of Quickening',slot:'amulet',desc:'March +2',lore:'A hummingbird in amber. March counts 2 levels higher.',effect:{stat:'march',bonus:2},tier:2},
  {name:'Talisman of the Wilds',slot:'amulet',desc:'Druid +2',lore:'A wolf-tooth strung on sinew that the wild things recognise. Druid counts 2 levels higher.',effect:{stat:'druid',bonus:2},tier:2},
  {name:'Amulet of the Quiet Mind',slot:'amulet',desc:'Amulet: spells and monster powers deal 20% less damage to you.',lore:'A smooth grey stone that dulls the sting of sorcery. Spells and guardian powers deal 20% less damage to you.',effect:{stat:'pc',pc:{ward:'spellPct',pct:20}},tier:1},
  {name:'Amulet of Second Breath',slot:'amulet',desc:'Amulet: once per fight, when first pushed near defeat you recover 20% of your maximum HP.',lore:'It warms when you are almost done. Once per fight, the first time you are driven near defeat you recover 20% of your maximum HP.',effect:{stat:'pc',pc:{ward:'secondWind',pct:20}},tier:2},
  {name:'Locket of the Watchful',slot:'amulet',desc:'Spy +2',lore:'Open it and it shows a face you were not looking for. Spy counts 2 levels higher.',effect:{stat:'spy',bonus:2},tier:2},
  {name:'Charm of the Lucky Coin',slot:'amulet',desc:'+2g collected each tax season (item tax gold is capped at 5% of your realm\'s base tax income)',lore:'A coin that always comes back with a friend. +2 gold each tax season.',effect:{stat:'taxBonus',bonus:2},tier:1},
  {name:'Amulet of the Seeker',slot:'amulet',desc:'Explorer +2',lore:'A lodestone that pulls toward the unmapped. Explorer counts 2 levels higher.',effect:{stat:'explorer',bonus:2},tier:2},
  // ── 2026-09-11: 44 further slot designs anyone can use — the thin categories first
  // (shields especially), so the balancing pass below has real designs to draw on rather than one shield
  // cloned a dozen times. ── Shields ──
  {name:'Buckler of the Quick Hand',slot:'shield',desc:'Shield: foes have −8% to hit you.',lore:'A small steel disc that is always exactly where the blow was going. Enemies have −8% to hit you in personal combat.',effect:{stat:'pc',pc:{ward:'dodge',pct:8}},tier:1},
  {name:'Hide Targe',slot:'shield',desc:'Shield: melee blows deal 1 less damage to you.',lore:'Boiled hide over a willow frame — cheap, light and better than nothing. Every melee blow that lands on you deals 1 less.',effect:{stat:'pc',pc:{ward:'meleeDR',amt:1}},tier:1},
  {name:'Banded Pavise',slot:'shield',desc:'Shield: arrows and missiles deal 3 less damage to you.',lore:'A tall shield a crossbowman hides behind while he winds. Every arrow or missile that strikes you deals 3 less.',effect:{stat:'pc',pc:{ward:'arrowDR',amt:3}},tier:1},
  {name:'Thorn-Rimmed Shield',slot:'shield',desc:'Shield: whoever lands a melee blow on you takes 2 damage back.',lore:'Its rim is set with iron barbs that bite the hand that strikes it. Anyone landing a melee blow on you takes 2 damage.',effect:{stat:'pc',pc:{ward:'thorns',amt:2}},tier:1},
  {name:'Shield of the Watchfire',slot:'shield',desc:'Shield: a foe in melee reach takes 1 fire damage every round.',lore:'The boss glows like a banked coal. Any foe at melee range takes 1 damage at the end of each round.',effect:{stat:'pc',pc:{burn:1}},tier:1},
  {name:'Wicker Warboard',slot:'shield',desc:'Shield: the first two hits to land on you each fight deal half damage.',lore:'Woven cane that gives before it breaks. The first two hits to land on you each fight deal half damage.',effect:{stat:'pc',pc:{ward:'openGuard',hits:2,pct:50}},tier:1},
  {name:'Shield of the Green Hill',slot:'shield',desc:'Shield: recover 1 HP at the start of every combat round.',lore:'Bound in living bark that closes its own cuts, and yours. Recover 1 HP at the start of every round.',effect:{stat:'pc',pc:{ward:'regen',amt:1}},tier:1},
  {name:'Scale-Faced Shield',slot:'shield',desc:'Shield: beasts, vermin and dragons deal 2 less damage to you.',lore:'Faced with the scales of something that used to hunt. Beasts, vermin and dragons deal 2 less with every hit.',effect:{stat:'pc',pc:{ward:'natureDR',amt:2}},tier:1},
  {name:'Shield of the Vigil',slot:'shield',desc:'Shield: undead and fiends deal 3 less damage to you.',lore:'Blessed on a night-long watch and never unblessed. Undead and fiends deal 3 less with every hit.',effect:{stat:'pc',pc:{ward:'darkDR',amt:3}},tier:1},
  {name:'Stormbreak Shield',slot:'shield',desc:'Shield: 25% chance to block any arrow or missile outright.',lore:'Angled to throw shafts aside like rain off a roof. 25% chance any arrow or missile is stopped outright.',effect:{stat:'pc',pc:{ward:'arrowBlock',pct:25}},tier:2},
  {name:'Shield of the Last Gate',slot:'shield',desc:'Shield: no single hit may cost you more than 25% of your maximum HP.',lore:'It held a gate once and has never learned to stop. No single hit costs more than a quarter of your maximum HP.',effect:{stat:'pc',pc:{ward:'cap',pct:25}},tier:2},
  {name:'Aegis of the Quiet Word',slot:'shield',desc:'Shield: spells and monster powers deal 30% less damage to you.',lore:'Sigils run its rim, and sorcery slides off them. Spells and guardian powers deal 30% less damage to you.',effect:{stat:'pc',pc:{ward:'spellPct',pct:30}},tier:2},
  {name:'Shield of the Unbowed',slot:'shield',desc:'Shield: while below half HP, every hit on you deals 25% less damage.',lore:'The worse it goes, the harder its bearer sets their feet. Below half HP every hit on you deals 25% less.',effect:{stat:'pc',pc:{ward:'lowHp',pct:25}},tier:2},
  {name:'Blackiron Heater',slot:'shield',desc:'Shield: melee blows deal 2 less damage to you.',lore:'Plain black iron, twice the weight and twice the worth. Every melee blow that lands on you deals 2 less.',effect:{stat:'pc',pc:{ward:'meleeDR',amt:2}},tier:2},
  // ── Armour ──
  {name:'Padded Gambeson',slot:'armour',desc:'Armour: arrows and missiles deal 2 less damage to you.',lore:'Twenty layers of quilted linen that swallow an arrowhead. Every arrow or missile that strikes you deals 2 less.',effect:{stat:'armour',ward:'arrowDR',amt:2},tier:1},
  {name:'Coat of Small Plates',slot:'armour',desc:'Armour: melee blows deal 1 less damage to you, and foes −5% to hit you.',lore:'Hundreds of overlapping plates riveted between cloth. Melee blows deal 1 less, and enemies have −5% to hit you.',effect:{stat:'armour',ward:'buckler'},tier:1},
  {name:'Salt-Crusted Mail',slot:'armour',desc:'Armour: recover 1 HP at the start of every combat round.',lore:'Mail hauled from a wreck; the sea gave it something back. Recover 1 HP at the start of every round.',effect:{stat:'armour',ward:'regen',amt:1},tier:1},
  {name:'Harness of the Long Vigil',slot:'armour',desc:'Armour: 15% chance any hostile spell or guardian power is turned away harmlessly.',lore:'Every strap is stamped with a ward-word. 15% chance a hostile spell or guardian power is turned aside entirely.',effect:{stat:'armour',ward:'spellBlock',pct:15},tier:2},
  // ── Helms ──
  {name:'Kettle Hat',slot:'helm',desc:'Helm: arrows and missiles deal 1 less damage to you.',lore:'A wide brim keeps the sky off a marching man. Arrows and missiles deal 1 less damage to you.',effect:{stat:'pc',pc:{ward:'arrowDR',amt:1}},tier:1},
  {name:'Horned Warhelm',slot:'helm',desc:'Helm: +2 damage on every successful melee attack.',lore:'You do not wear this to hide behind it. Every melee hit you land deals 2 extra damage.',effect:{stat:'pc',pc:{dmgBonus:2}},tier:1},
  {name:'Coif of the Deep Roads',slot:'helm',desc:'Helm: recover 1 HP at the start of every combat round.',lore:'Mail worn smooth by years underground, and warm in the worst of it. Recover 1 HP at the start of every round.',effect:{stat:'pc',pc:{ward:'regen',amt:1}},tier:1},
  {name:'Crown of the Quiet Court',slot:'helm',desc:'White Magic +1',lore:'A slim gold band worn by those who judge rather than fight. White Magic counts 1 level higher.',effect:{stat:'white',bonus:1},tier:1},
  {name:'Bone Diadem',slot:'helm',desc:'Necromancy +1',lore:'Carved from a skull that answered questions after it died. Necromancy counts 1 level higher.',effect:{stat:'necromancy',bonus:1},tier:1},
  {name:'Helm of the Salamander',slot:'helm',desc:'Helm: burns, poisons and bleeding never take hold on you.',lore:'Nothing lit inside it has ever stayed lit. No burn, poison or bleed takes hold on you.',effect:{stat:'pc',pc:{ward:'dotImmune'}},tier:2},
  // ── Cloaks ──
  {name:'Oilskin Cloak',slot:'cloak',desc:'Cloak: arrows and missiles deal 1 less damage to you.',lore:'Heavy, waxed and stiff enough to turn a spent shaft. Arrows and missiles deal 1 less damage to you.',effect:{stat:'pc',pc:{ward:'arrowDR',amt:1}},tier:1},
  {name:'Mantle of the Second Wind',slot:'cloak',desc:'Cloak: once per fight, when first pushed near defeat you recover 15% of your maximum HP.',lore:'It tightens at the shoulders when the legs begin to go. Once per fight, driven near defeat, you recover 15% of your maximum HP.',effect:{stat:'pc',pc:{ward:'secondWind',pct:15}},tier:2},
  {name:'Cloak of the Cold Hearth',slot:'cloak',desc:'Cloak: undead and fiends deal 2 less damage to you.',lore:'Grave-cold to the touch, and the grave-cold thing finds nothing in it. Undead and fiends deal 2 less with every hit.',effect:{stat:'pc',pc:{ward:'darkDR',amt:2}},tier:1},
  {name:'Beastward Mantle',slot:'cloak',desc:'Cloak: beasts, vermin and dragons deal 2 less damage to you.',lore:'Sewn with the musk of a bigger predator. Beasts, vermin and dragons deal 2 less with every hit.',effect:{stat:'pc',pc:{ward:'natureDR',amt:2}},tier:1},
  {name:'Cloak of the Pale Hours',slot:'cloak',desc:'Cloak: +5% to hit in personal combat.',lore:'Worn thin at the hem from too many night marches; its wearer sees the opening first. +5% to hit in personal combat.',effect:{stat:'pc',pc:{hitBonus:5}},tier:1},
  {name:'Sage\'s Travelling Cloak',slot:'cloak',desc:'Sage +1',lore:'Deep pockets full of notes nobody else can read. Sage counts 1 level higher.',effect:{stat:'sage',bonus:1},tier:1},
  // ── Rings ──
  {name:'Ring of the Ironbound',slot:'ring',desc:'Ring: melee blows deal 1 less damage to you.',lore:'A plain band that seems to take some of the weight of a blow. Melee blows deal 1 less damage to you.',effect:{stat:'pc',pc:{ward:'meleeDR',amt:1}},tier:1},
  {name:'Ring of Small Mercies',slot:'ring',desc:'Ring: recover 1 HP at the start of every combat round.',lore:'It warms a little with every wound taken. Recover 1 HP at the start of every round.',effect:{stat:'pc',pc:{ward:'regen',amt:1}},tier:1},
  {name:'Ring of the Coiled Serpent',slot:'ring',desc:'Ring: +2 damage on every successful melee attack.',lore:'The serpent tightens when the hand does. Every melee hit you land deals 2 extra damage.',effect:{stat:'pc',pc:{dmgBonus:2}},tier:1},
  {name:'Ring of the Counting House',slot:'ring',desc:'+3g collected each tax season (item tax gold is capped at 5% of your realm\'s base tax income)',lore:'A merchant\'s seal that still opens doors. +3 gold each tax season.',effect:{stat:'taxBonus',bonus:3},tier:1},
  // ── Amulets ──
  {name:'Charm of the Ash Grove',slot:'amulet',desc:'Amulet: burns, poisons and bleeding never take hold on you.',lore:'A knot of grey ashwood that draws poison out. No burn, poison or bleed takes hold on you.',effect:{stat:'pc',pc:{ward:'dotImmune'}},tier:1},
  {name:'Pendant of the Grave-Warden',slot:'amulet',desc:'Amulet: undead and fiends deal 3 less damage to you.',lore:'Worn by those whose work is in the cold ground. Undead and fiends deal 3 less with every hit.',effect:{stat:'pc',pc:{ward:'darkDR',amt:3}},tier:1},
  {name:'Talisman of the Steady Eye',slot:'amulet',desc:'Amulet: +10% to hit in personal combat.',lore:'A polished disc that pulls the gaze straight. +10% to hit with every attack in personal combat.',effect:{stat:'pc',pc:{hitBonus:10}},tier:2},
  {name:'Amulet of the Deep Root',slot:'amulet',desc:'Amulet: recover 2 HP at the start of every combat round.',lore:'A knotted root that keeps drawing on something far below. Recover 2 HP at the start of every round.',effect:{stat:'pc',pc:{ward:'regen',amt:2}},tier:2},
  {name:'Charm of the Turned Blade',slot:'amulet',desc:'Amulet: melee blows deal 1 less damage to you.',lore:'A bent nail on a thong; it was bent stopping something. Melee blows deal 1 less damage to you.',effect:{stat:'pc',pc:{ward:'meleeDR',amt:1}},tier:1},
  {name:'Locket of the Hearthkeeper',slot:'amulet',desc:'Max HP +4',lore:'Someone at home is still waiting, and it matters. Maximum HP +4.',effect:{stat:'maxHp',bonus:4},tier:1},
  // ── 2026-09-11: 41 further combat items, so the Combat Item slot is as deep as every worn slot
  // (90). One name per effect, as ruled in 84.3 — these are new DESIGNS, not renamed copies.
  {name:'Draught of the Badger',desc:'Combat use: recover 6 HP once per fight (drunk when below 60% health).',lore:'Thick, bitter and brewed by people who expect to be bitten. Used once per personal combat when below 60% health: recover 6 HP.',effect:{stat:'combatUse',use:'heal',amt:6,below:0.6,bonus:0},tier:1},
  {name:'Surgeon\'s Flask',desc:'Combat use: recover 11 HP once per fight (drunk when below half health).',lore:'Spirits strong enough to clean a wound and dull it at once. Used once per personal combat below half health: recover 11 HP.',effect:{stat:'combatUse',use:'heal',amt:11,below:0.5,bonus:0},tier:2},
  {name:'Vial of Deep Water',desc:'Combat use: recover 4 HP once per fight (drunk when badly hurt).',lore:'Drawn from a spring nobody can find twice. Used once per personal combat when badly hurt: recover 4 HP.',effect:{stat:'combatUse',use:'heal',amt:4,below:0.4,bonus:0},tier:1},
  {name:'Poultice of Bright Moss',desc:'Combat use: heal 2 HP at the start of each of the next 5 rounds.',lore:'Moss that keeps glowing after it is picked, and keeps working after it is packed into a wound. 2 HP a round for five rounds.',effect:{stat:'combatUse',use:'hot',amt:2,rounds:5,below:0.7,bonus:0},tier:1},
  {name:'Tincture of Slow Mending',desc:'Combat use: heal 4 HP at the start of each of the next 3 rounds.',lore:'It works from the inside out, and it is not gentle. 4 HP a round for three rounds.',effect:{stat:'combatUse',use:'hot',amt:4,rounds:3,below:0.7,bonus:0},tier:2},
  {name:'Cordial of the Last Breath',desc:'Combat use: recover 12 HP and shed every poison, burn and blinding (drunk when nearly spent).',lore:'Kept for the moment there is nothing else left to try. Recover 12 HP, and every lingering affliction lifts.',effect:{stat:'combatUse',use:'secondwind',amt:12,below:0.5,bonus:0},tier:2},
  {name:'Scroll of Hailstones',desc:'Combat use: a battering of ice for 6-11 damage, once per fight.',lore:'The air above the foe turns white and falls on them. 6-11 damage, once per fight.',effect:{stat:'combatUse',use:'dmg',dmg:[6,11],bonus:0},tier:1},
  {name:'Scroll of the Riving Wind',desc:'Combat use: a cutting gale for 9-15 damage, once per fight.',lore:'A wind with edges in it. 9-15 damage, once per fight.',effect:{stat:'combatUse',use:'dmg',dmg:[9,15],bonus:0},tier:2},
  {name:'Vial of Green Vitriol',desc:'Combat use: 5-9 damage and the acid keeps eating for 2 a round, three rounds.',lore:'It goes through mail the way rain goes through paper. 5-9 damage, then 2 a round for three rounds.',effect:{stat:'combatUse',use:'dmg',dmg:[5,9],dot:[2,3],bonus:0},tier:1},
  {name:'Firepot of the Siegeworks',desc:'Combat use: 7-12 damage and the foe burns for 3 a round, two rounds.',lore:'A clay pot of something the engineers will not name. 7-12 damage, then 3 a round for two rounds.',effect:{stat:'combatUse',use:'dmg',dmg:[7,12],dot:[3,2],bonus:0},tier:2},
  {name:'Scroll of the Splitting Bolt',desc:'Combat use: two bolts of 4-7 damage each, once per fight.',lore:'One word, two answers. Two strikes of 4-7 damage.',effect:{stat:'combatUse',use:'dmg',dmg:[4,7],times:2,bonus:0},tier:2},
  {name:'Handful of Iron Filings',desc:'Combat use: 3-6 damage and the foe is blinded (-15% to hit).',lore:'Thrown into the eyes by someone who has stopped fighting fair. 3-6 damage, and the foe is -15% to hit.',effect:{stat:'combatUse',use:'dmg',dmg:[3,6],hitPen:15,bonus:0},tier:1},
  {name:'Screaming Skull',desc:'Combat use: 6-10 damage and the foe loses their next action.',lore:'It screams once, and whoever hears it loses a moment they needed. 6-10 damage and one action lost.',effect:{stat:'combatUse',use:'dmg',dmg:[6,10],stun:1,bonus:0},tier:2},
  {name:'Scroll of the Barbed Word',desc:'Combat use: 8-13 damage, once per fight.',lore:'A syllable that lodges somewhere it should not. 8-13 damage, once per fight.',effect:{stat:'combatUse',use:'dmg',dmg:[8,13],bonus:0},tier:2},
  {name:'Caltrop Pouch',desc:'Combat use: 2-5 damage and the foe is slowed (-10% to hit).',lore:'Scattered underfoot, and suddenly nobody is advancing. 2-5 damage and -10% to hit.',effect:{stat:'combatUse',use:'dmg',dmg:[2,5],hitPen:10,bonus:0},tier:1},
  {name:'Phial of Black Bile',desc:'Combat use: 4-8 damage to the foe, and you recover the same.',lore:'It takes something out of them and puts it into you. 4-8 damage, and you recover as much.',effect:{stat:'combatUse',use:'drain',dmg:[4,8],below:0.75,bonus:0},tier:1},
  {name:'Chalice of the Leech',desc:'Combat use: 7-11 damage to the foe, and you recover the same.',lore:'A cup with no bottom worth speaking of. 7-11 damage, and you recover as much.',effect:{stat:'combatUse',use:'drain',dmg:[7,11],below:0.75,bonus:0},tier:2},
  {name:'Net of Fine Chain',desc:'Combat use: the foe is tangled and loses their next action.',lore:'Weighted silver links that close as they fall. The foe loses one action.',effect:{stat:'combatUse',use:'stun',stun:1,bonus:0},tier:1},
  {name:'Scroll of the Binding Word',desc:'Combat use: the foe is held and loses their next 2 actions.',lore:'A word of holding, spoken once and obeyed twice. The foe loses two actions.',effect:{stat:'combatUse',use:'stun',stun:2,bonus:0},tier:2},
  {name:'Flash Powder',desc:'Combat use: the foe is dazzled — -20% to hit for the rest of the fight.',lore:'A white bang and a long green afterimage. The foe is -20% to hit.',effect:{stat:'combatUse',use:'pen',hitPen:20,bonus:0},tier:1},
  {name:'Pot of Clinging Pitch',desc:'Combat use: the foe fights half-blind — -25% to hit for the rest of the fight.',lore:'Black, sticky and impossible to wipe away in a hurry. The foe is -25% to hit.',effect:{stat:'combatUse',use:'pen',hitPen:25,bonus:0},tier:2},
  {name:'Scroll of the Leaden Arm',desc:'Combat use: the foe\'s Melee drops 2 for the rest of the fight.',lore:'Their sword weighs what an anvil weighs. The foe\'s Melee counts 2 lower.',effect:{stat:'combatUse',use:'weak',melee:2,bonus:0},tier:2},
  {name:'Scroll of the Slackened String',desc:'Combat use: the foe\'s Archery drops 2 for the rest of the fight.',lore:'Every bowstring within earshot goes soft. The foe\'s Archery counts 2 lower.',effect:{stat:'combatUse',use:'weak',archery:2,bonus:0},tier:1},
  {name:'Wailing Horn',desc:'Combat use: a living foe must hold their nerve or flee; the fearless fight on shaken (-20% to hit).',lore:'One long note that sounds like something losing. The foe flees, or fights on at -20% to hit.',effect:{stat:'combatUse',use:'terror',hitPen:20,bonus:0},tier:2},
  {name:'Scroll of the Stilled Tongue',desc:'Combat use: the foe\'s magic and powers are bound for 4 rounds.',lore:'Their throat works and nothing comes out. Four rounds of silence.',effect:{stat:'combatUse',use:'silence',rounds:4,bonus:0},tier:2},
  {name:'Bell of Quiet Hours',desc:'Combat use: the foe\'s magic and powers are bound for 2 rounds.',lore:'Rung once, it takes the noise out of the air — and the words out of a spell. Two rounds of silence.',effect:{stat:'combatUse',use:'silence',rounds:2,bonus:0},tier:1},
  {name:'Draught of the Boar',desc:'Combat use: Melee +2 for the rest of the fight.',lore:'Drunk by people who intend to go straight through. Melee counts 2 higher.',effect:{stat:'combatUse',use:'buff',melee:2,bonus:0},tier:2},
  {name:'Draught of the Steady Draw',desc:'Combat use: Archery +2 for the rest of the fight.',lore:'It slows the heart until the shot chooses itself. Archery counts 2 higher.',effect:{stat:'combatUse',use:'buff',archery:2,bonus:0},tier:2},
  {name:'Hunter\'s Tonic',desc:'Combat use: Archery +1 for the rest of the fight.',lore:'Bitter bark and cold water, drunk before the beaters go in. Archery counts 1 higher.',effect:{stat:'combatUse',use:'buff',archery:1,bonus:0},tier:1},
  {name:'Oil of the Keen Eye',desc:'Combat use: +15% to hit for the rest of the fight.',lore:'A drop at each temple and the world stops shifting. +15% to hit.',effect:{stat:'combatUse',use:'focus',hitBonus:15,bonus:0},tier:2},
  {name:'Chalk of the Duellist',desc:'Combat use: +7% to hit for the rest of the fight.',lore:'Rubbed into the palm before the first pass. +7% to hit.',effect:{stat:'combatUse',use:'focus',hitBonus:7,bonus:0},tier:1},
  {name:'Charm of the Standing Stone',desc:'Combat use: a ward that soaks 6 damage.',lore:'A chip of a stone that has stood through worse. A ward that drinks the next 6 damage.',effect:{stat:'combatUse',use:'absorb',absorb:6,bonus:0},tier:1},
  {name:'Scroll of the Thorned Ward',desc:'Combat use: a ward that soaks 10 damage and bites back for 3 on every hit.',lore:'The ward has spines on the inside. Soaks 10 damage and bites back for 3.',effect:{stat:'combatUse',use:'absorb',absorb:10,reflect:3,bonus:0},tier:2},
  {name:'Scroll of the Glass Skin',desc:'Combat use: a ward that soaks 14 damage.',lore:'It looks like nothing and stops a great deal. A ward that drinks the next 14 damage.',effect:{stat:'combatUse',use:'absorb',absorb:14,bonus:0},tier:2},
  {name:'Powder of Three Shadows',desc:'Combat use: three mirror images that each soak one blow.',lore:'Thrown over the shoulder; three of you walk on. Three images, one blow each.',effect:{stat:'combatUse',use:'mirror',images:3,below:0.7,bonus:0},tier:2},
  {name:'Grey Cloak Draught',desc:'Combat use: the foe strikes at shadows — -20% to hit you.',lore:'You are still there; you are simply very hard to attend to. The foe is -20% to hit you.',effect:{stat:'combatUse',use:'invis',toHitReduce:20,bonus:0},tier:1},
  {name:'Ash of the Hearth-Fire',desc:'Combat use: +30% to any flight attempt (thrown when badly hurt).',lore:'A grey cloud and a smell of home; nobody follows through it. +30% to break away.',effect:{stat:'combatUse',use:'flee',fleeBonus:30,below:0.35,bonus:0},tier:1},
  {name:'Whistle of the Waiting Horse',desc:'Combat use: +50% to any flight attempt, and the foe -10% to hit (used when badly hurt).',lore:'Something loyal is closer than the foe realised. +50% to break away, and the foe -10% to hit.',effect:{stat:'combatUse',use:'flee',fleeBonus:50,toHitReduce:10,below:0.35,bonus:0},tier:2},
  {name:'Draught of Clean Blood',desc:'Combat use: every poison, burn and blinding on you lifts at once.',lore:'It tastes of nothing at all, which is the point. Every lingering affliction lifts.',effect:{stat:'combatUse',use:'dispel',bonus:0},tier:1},
  {name:'Silver-Tipped Bolt',desc:'Combat use: 13-19 damage against undead and fiends only.',lore:'Cast for one purpose and useless for any other. 13-19 damage to undead and fiends.',effect:{stat:'combatUse',use:'bane',dmg:[13,19],vs:['undead','fiend'],bonus:0},tier:2},
  {name:'Wyrm-Salt Charge',desc:'Combat use: 12-17 damage against beasts and dragons only.',lore:'Salt from a bed a dragon once slept in; its kin cannot abide it. 12-17 damage to beasts and dragons.',effect:{stat:'combatUse',use:'bane',dmg:[12,17],vs:['beast','dragon'],bonus:0},tier:1},
  // ── 2026-09-24 THE FOUR-TIER RE-CUT (Toby): Weak lairs hold only the kit of heroes doing OTHER jobs;
  // Moderate the first rung of combat kit; Powerful the second. The GM portal now bands every item by
  // ROLE (itemRole) and then by strength, so the `tier` written here is only a hint. Two things were
  // short once the bands were re-cut and are written here: ──
  // (a) FIELD & OFFICE KIT for the Weak band — helms, cloaks, rings, amulets and trinkets for the
  //     army-leader, the spy, the explorer, the reeve. Nothing here does a thing in a fight.
  {name:'Cap of the Outrider',desc:'March +1.',lore:'A soft leather cap that has ridden further than most men walk. March skill counts as 1 level higher.',effect:{stat:'march',bonus:1},slot:'helm',tier:1},
  {name:'Hood of the Cutpurse',desc:'Thief +1.',lore:'Deep enough to hide the eyes and the intent behind them. Thief skill counts as 1 level higher.',effect:{stat:'thief',bonus:1},slot:'helm',tier:1},
  {name:'Coif of the Ledger-Keeper',desc:'Tax income +3% (capped with all bonus tax at 5% of base).',lore:'Worn by the reeve who counted every sheaf twice. Tax income +3%, under the realm\'s ceiling on bonus gold.',effect:{stat:'taxBonus',bonus:3},slot:'helm',tier:1},
  {name:'Circlet of the Quartermaster',desc:'Infantry you lead fight +20%.',lore:'A plain iron band; the men who see it know their lines will hold and their rations will come. Shieldwall, Guard and Berserker units you lead fight at +20%.',effect:{stat:'infBonus',bonus:1},slot:'helm',tier:1},
  {name:'Helm of the Lancer-Captain',desc:'Cavalry you lead fight +25%.',lore:'Its plume has led more charges than its wearers. Lances, riders and winged cavalry you lead fight at +25%.',effect:{stat:'cavBonus',bonus:1},slot:'helm',tier:1},
  {name:'Cap of the Master Bowman',desc:'Archer units you lead fight +30%.',lore:'Green felt, one hawk feather, and a way of reading the wind. Longbow, Bowmen, Shadow Archer and Crossbow units you lead fight at +30%.',effect:{stat:'archerStr',bonus:1},slot:'helm',tier:1},
  {name:'Salt-Stained Captain\'s Hat',desc:'Naval +1.',lore:'It has been over the side twice and come back both times. Naval skill counts as 1 level higher.',effect:{stat:'naval',bonus:1},slot:'helm',tier:1},
  {name:'Crown of the Dead Legion',desc:'Skeletal units you lead fight +4.',lore:'A verdigrised circlet lifted from a barrow-lord; the risen know the shape of it. Every skeletal unit you lead fights at +4 strength.',effect:{stat:'undeadBonus',bonus:1},slot:'helm',tier:1},
  {name:'Mantle of the Marches',desc:'Armies you lead in your own provinces fight +1 level.',lore:'Sewn from the border-flags of a realm that never lost a hearth. In your own provinces the armies you lead fight as if a level stronger.',effect:{stat:'homeDefBonus',bonus:1},slot:'cloak',tier:1},
  {name:'Cloak of the Siege Engineer',desc:'Siege bonus +1.',lore:'Pockets full of chalk, string and small hard arithmetic. Your armies breach walls as if a level stronger.',effect:{stat:'siegeBonus',bonus:1},slot:'cloak',tier:1},
  {name:'Riverman\'s Oilcloth',desc:'Naval +1.',lore:'It keeps out the wet and it knows every ford by heart. Naval skill counts as 1 level higher.',effect:{stat:'naval',bonus:1},slot:'cloak',tier:1},
  {name:'Cloak of the Shieldwall',desc:'Infantry you lead never break ranks.',lore:'Cut short so it never fouls a shield-arm. The foot you lead hold their line to the last.',effect:{stat:'infStay',bonus:1},slot:'cloak',tier:1},
  {name:'Herald\'s Tabard',desc:'Tactical +1.',lore:'The colours are faded but every captain still stands straighter when it passes. Tactical skill counts as 1 level higher.',effect:{stat:'tactical',bonus:1},slot:'cloak',tier:1},
  {name:'Cloak of the Tithe-Reeve',desc:'+1 gold per province you hold, each turn (capped with all bonus tax).',lore:'Lined with pockets, every one of which has held someone else\'s coin. Each province you hold yields 1 extra gold a turn, under the realm\'s ceiling on bonus gold.',effect:{stat:'taxPerProv',bonus:1},slot:'cloak',tier:1},
  {name:'Pilgrim\'s Dustcloak',desc:'Explorer +1.',lore:'Grey with the dust of roads that were not on any map. Explorer skill counts as 1 level higher.',effect:{stat:'explorer',bonus:1},slot:'cloak',tier:1},
  {name:'Mantle of the Grave-Speaker',desc:'Necromancy +1.',lore:'Cold to the touch on the warmest day; the dead lean in to listen. Necromancy skill counts as 1 level higher.',effect:{stat:'necromancy',bonus:1},slot:'cloak',tier:1},
  {name:'Ring of the Drover',desc:'Druid +1.',lore:'Horn, worn smooth by a thumb that has calmed a thousand beasts. Druid skill counts as 1 level higher.',effect:{stat:'druid',bonus:1},slot:'ring',tier:1},
  {name:'Ring of the Sapper',desc:'Siege bonus +1.',lore:'Iron, scored with a plan of walls that are no longer standing. Your armies breach walls as if a level stronger.',effect:{stat:'siegeBonus',bonus:1},slot:'ring',tier:1},
  {name:'Band of the Home Guard',desc:'Armies you lead in your own provinces fight +1 level.',lore:'Given to the captain who stayed when the others rode out. In your own provinces the armies you lead fight as if a level stronger.',effect:{stat:'homeDefBonus',bonus:1},slot:'ring',tier:1},
  {name:'Ring of the Lancer',desc:'Cavalry you lead fight +25%.',lore:'A spur-rowel set in silver. Lances, riders and winged cavalry you lead fight at +25%.',effect:{stat:'cavBonus',bonus:1},slot:'ring',tier:1},
  {name:'Ring of the Whispered Word',desc:'Psychic +1.',lore:'You hear the sentence before it is spoken. Psychic skill counts as 1 level higher.',effect:{stat:'psychic',bonus:1},slot:'ring',tier:1},
  {name:'Ring of the Assessor',desc:'Tax income +3% (capped with all bonus tax at 5% of base).',lore:'Nothing in the realm is worth quite what its owner says, and the ring knows it. Tax income +3%, under the realm\'s ceiling on bonus gold.',effect:{stat:'taxBonus',bonus:3},slot:'ring',tier:1},
  {name:'Pendant of the Wayfarer',desc:'March +1.',lore:'A road-stone on a cord; the feet under it do not tire. March skill counts as 1 level higher.',effect:{stat:'march',bonus:1},slot:'amulet',tier:1},
  {name:'Amulet of the Far Shore',desc:'Naval +1.',lore:'Coral from a reef no chart shows. Naval skill counts as 1 level higher.',effect:{stat:'naval',bonus:1},slot:'amulet',tier:1},
  {name:'Locket of the Informer',desc:'Spy +1.',lore:'Inside is a face nobody living recognises. Spy skill counts as 1 level higher.',effect:{stat:'spy',bonus:1},slot:'amulet',tier:1},
  {name:'Talisman of the Sneak-Thief',desc:'Thief +1.',lore:'It has been stolen so often it comes when called. Thief skill counts as 1 level higher.',effect:{stat:'thief',bonus:1},slot:'amulet',tier:1},
  {name:'Scholar\'s Medallion',desc:'Sage +1.',lore:'Struck for a college that argued itself out of existence. Sage skill counts as 1 level higher.',effect:{stat:'sage',bonus:1},slot:'amulet',tier:1},
  {name:'Charm of the Wild Road',desc:'Explorer +1.',lore:'A bent nail, a bead and a knot of hair; it has never once been lost. Explorer skill counts as 1 level higher.',effect:{stat:'explorer',bonus:1},slot:'amulet',tier:1},
  {name:'Talisman of the Herd-Caller',desc:'Druid +1.',lore:'A wolf\'s tooth and a lamb\'s, on the same thong. Druid skill counts as 1 level higher.',effect:{stat:'druid',bonus:1},slot:'amulet',tier:1},
  {name:'Medal of the Drill-Sergeant',desc:'Infantry you lead fight +20%.',lore:'Bronze, and it has been thrown at people. Shieldwall, Guard and Berserker units you lead fight at +20%.',effect:{stat:'infBonus',bonus:1},slot:'amulet',tier:1},
  {name:'Amulet of the Bombardier',desc:'Heavy engines you lead fight +4.',lore:'A powder-flask stopper on a chain, still faintly warm. Mountain Guns and Ironclads you lead fight at +4 strength.',effect:{stat:'heavyBonus',bonus:1},slot:'amulet',tier:1},
  {name:'Torc of the Warband',desc:'Every army you lead fights +2.',lore:'Twisted gold, the old way; a warband follows the neck it sits on. Every army you lead fights at +2 strength.',effect:{stat:'armyBonus',bonus:2},slot:'amulet',tier:1},
  {name:'Muster Roll of the Free Companies',desc:'Every army you lead fights +2.',lore:'Every name on it is a debt owed to you. Every army you lead fights at +2 strength.',effect:{stat:'armyBonus',bonus:2},tier:1},
  {name:'Siege-Wright\'s Scale Model',desc:'Siege bonus +1.',lore:'A tower in miniature; the full-size one goes up in half the time. Your armies breach walls as if a level stronger.',effect:{stat:'siegeBonus',bonus:1},tier:1},
  {name:'Standard of the Home Levy',desc:'Armies you lead in your own provinces fight +1 level.',lore:'Patched by a hundred hands who all had somewhere to defend. In your own provinces the armies you lead fight as if a level stronger.',effect:{stat:'homeDefBonus',bonus:1},tier:1},
  {name:'Falconer\'s Glove',desc:'Spy +1.',lore:'Something comes back to it at dusk with news. Spy skill counts as 1 level higher.',effect:{stat:'spy',bonus:1},tier:1},
  {name:'Surveyor\'s Chain',desc:'Explorer +1.',lore:'Sixty-six feet of iron links that have measured every field between here and the sea. Explorer skill counts as 1 level higher.',effect:{stat:'explorer',bonus:1},tier:1},
  {name:'Tally-Sticks of the Reeve',desc:'Tax income +3% (capped with all bonus tax at 5% of base).',lore:'Notched hazel; nobody has ever successfully argued with them. Tax income +3%, under the realm\'s ceiling on bonus gold.',effect:{stat:'taxBonus',bonus:3},tier:1},
  // (b) SECOND-RUNG COMBAT ACCESSORIES for the Powerful band — the treasury had almost no ring, helm,
  //     cloak or amulet strong enough to be a Powerful find, and few armours or shields.
  {name:'Ring of the Sworn Blade',desc:'Melee +2.',lore:'Worn on the sword-hand; the oath is in the metal. Melee skill counts as 2 levels higher.',effect:{stat:'melee',bonus:2},slot:'ring',tier:3},
  {name:'Ring of the Longshot',desc:'Archery +2.',lore:'A ring of horn cut from a bow that never missed. Archery skill counts as 2 levels higher.',effect:{stat:'archery',bonus:2},slot:'ring',tier:3},
  {name:'Band of the Bull\'s Heart',desc:'Max HP +8.',lore:'Heavy, red-gold, and the pulse under it is slow and strong. Maximum HP +8.',effect:{stat:'maxHp',bonus:8},slot:'ring',tier:3},
  {name:'Ring of the Unbroken Pulse',desc:'15% to shrug off a killing blow once per fight, standing at 1 HP.',lore:'The stone flickers once, and you are still standing. Once per fight, 15% to survive a killing blow at 1 HP.',effect:{stat:'pc',pc:{ward:'secondWind',pct:15}},slot:'ring',tier:3},
  {name:'Ring of the Ember Tongue',desc:'Elemental +2.',lore:'Warm as a hearth-stone; the words come out lit. Elemental skill counts as 2 levels higher.',effect:{stat:'elemental',bonus:2},slot:'ring',tier:3},
  {name:'Ring of the Lantern-Bearer',desc:'White +2.',lore:'A small clear light that the dark has learned to avoid. White skill counts as 2 levels higher.',effect:{stat:'white',bonus:2},slot:'ring',tier:3},
  {name:'Ring of Seven Masks',desc:'Illusory +2.',lore:'Turn it and a different face looks back from every polished surface. Illusory skill counts as 2 levels higher.',effect:{stat:'illusory',bonus:2},slot:'ring',tier:3},
  {name:'Ring of the Butcher',desc:'+10% to hit and +3 damage on every hit.',lore:'Nothing elegant about it; it simply lands, and lands hard. +10% to hit and +3 damage on every hit you make.',effect:{stat:'pc',pc:{hitBonus:10,dmgBonus:3}},slot:'ring',tier:3},
  {name:'Warhelm of the Champion',desc:'Melee +2.',lore:'Dented in three tourneys and dented nobody else\'s. Melee skill counts as 2 levels higher.',effect:{stat:'melee',bonus:2},slot:'helm',tier:3},
  {name:'Helm of the Iron Constitution',desc:'Max HP +8.',lore:'Padded with something that does not seem to be cloth. Maximum HP +8.',effect:{stat:'maxHp',bonus:8},slot:'helm',tier:3},
  {name:'Great Helm of the Deathless',desc:'20% to shrug off a killing blow once per fight, standing at 1 HP.',lore:'Its last three owners were each certain they had died in it. Once per fight, 20% to survive a killing blow at 1 HP.',effect:{stat:'pc',pc:{ward:'secondWind',pct:20}},slot:'helm',tier:3},
  {name:'Cloak of the Duellist',desc:'Melee +2.',lore:'Cut to swing clear of the blade and to be seen doing it. Melee skill counts as 2 levels higher.',effect:{stat:'melee',bonus:2},slot:'cloak',tier:3},
  {name:'Mantle of the Marksman',desc:'Archery +2.',lore:'Hooded, quiet, and the colour of whatever is behind you. Archery skill counts as 2 levels higher.',effect:{stat:'archery',bonus:2},slot:'cloak',tier:3},
  {name:'Cloak of the Ember Heart',desc:'Elemental +2.',lore:'It never quite stops smouldering. Elemental skill counts as 2 levels higher.',effect:{stat:'elemental',bonus:2},slot:'cloak',tier:3},
  {name:'Amulet of the Bear\'s Blood',desc:'Max HP +10.',lore:'A claw in a silver cage; the strength of the animal did not leave with it. Maximum HP +10.',effect:{stat:'maxHp',bonus:10},slot:'amulet',tier:3},
  {name:'Talisman of the Slayer',desc:'+10% to hit and +3 damage on every hit.',lore:'Teeth, mostly, from things that had teeth of their own. +10% to hit and +3 damage on every hit you make.',effect:{stat:'pc',pc:{hitBonus:10,dmgBonus:3}},slot:'amulet',tier:3},
  {name:'Harness of the Vanguard',desc:'Melee damage taken −3, and +8% to hit.',lore:'The first into every breach and still in one piece. Every melee blow against you deals 3 less, and you strike at +8% to hit.',effect:{stat:'armour',ward:'meleeDR',amt:3,bonus:0,pc:{hitBonus:8}},slot:'armour',tier:3},
  {name:'Coat of the Living Oak',desc:'Regain 3 HP a round, and every foe that strikes you takes 2.',lore:'Bark that is still, in some slow way, growing. You regain 3 HP every round, and a foe that strikes you in melee takes 2 back.',effect:{stat:'armour',ward:'regen',amt:3,bonus:0,pc:{ward:'thorns',amt:2}},slot:'armour',tier:3},
  {name:'Mail of the Storm-Warden',desc:'Spell damage −40%, and 10% to dodge any blow.',lore:'The rings hum in a thunderstorm and lightning goes elsewhere. Spells deal 40% less to you, and you dodge 10% of blows outright.',effect:{stat:'armour',ward:'spellPct',pct:40,bonus:0,pc:{ward:'dodge',pct:10}},slot:'armour',tier:3},
  {name:'Breastplate of the Undaunted',desc:'No single blow deals more than 30% of your max HP, and you cannot be stunned.',lore:'Whatever hits it, you are still on your feet and still thinking. No one blow takes more than 30% of your maximum HP, and nothing stuns you.',effect:{stat:'armour',ward:'cap',pct:30,bonus:0,pc:{ward:'stunImmune'}},slot:'armour',tier:3},
  {name:'Bulwark of the Marches',desc:'Blocks 40% of arrows, and melee damage taken −1.',lore:'Tall, iron-rimmed, and full of other people\'s arrows. Blocks 40% of missiles, and every melee blow against you deals 1 less.',effect:{stat:'armour',ward:'arrowBlock',pct:40,bonus:0,pc:{ward:'meleeDR',amt:1}},slot:'shield',tier:3},
  {name:'Shield of Quenched Flame',desc:'Blocks 35% of spells, and no poison or burn can take hold on you.',lore:'Cooled in a river the moment it left the forge; fire has never forgiven it. Blocks 35% of spells cast at you, and no lingering poison or burn can take hold.',effect:{stat:'armour',ward:'spellBlock',pct:35,bonus:0,pc:{ward:'dotImmune'}},slot:'shield',tier:3},
  {name:'Wall of the Ninth Legion',desc:'Blocks 30% of blows, and no single blow deals more than 20% of your max HP.',lore:'A legion once stood behind it; the shield remembers the drill. Blocks 30% of blows, and no one blow takes more than 20% of your maximum HP.',effect:{stat:'armour',ward:'block',pct:30,bonus:0,pc:{ward:'cap',pct:20}},slot:'shield',tier:3},
  {name:'Roundshield of the Watch-Fire',desc:'The first 3 blows against you are half-turned, and a foe at close quarters is singed for 1 a round.',lore:'Its boss is a brazier; the first men over the wall regret it. The first 3 blows against you deal half, and any foe at melee range takes 1 each round.',effect:{stat:'armour',ward:'openGuard',hits:3,pct:50,bonus:0,pc:{burn:1}},slot:'shield',tier:3},
];

